// Üretilen dosya: tool/ozgun/uret.py. Toplum ve Sosyal Bilimler · İletişim bilimleri, medya kuramları ve medya okuryazarlığı (gündem belirleme, suskunluk sarmalı, çerçeveleme, yankı odası, dezenformasyon) (orta).
const ozSocialscience16Orta = <(String, String, List<String>, String)>[
  ('Wilbur Schramm\'ın iletişim modeline göre kaynak ile alıcı arasında sağlıklı bir kodlama ve kodaçımı gerçekleşebilmesi hangi temel koşula bağlıdır?', 'Tarafların ortak yaşantı ve deneyim alanlarının kesişmesine', ['Mesajın yalnızca yazılı ve resmî kanallar üzerinden iletilmesine', 'Kaynağın alıcı üzerinde hiyerarşik yaptırım gücüne sahip olmasına', 'İletişim sürecinde geri bildirim mekanizmasının tamamen devre dışı bırakılmasına'], 'Schramm modelinde kaynağın ve alıcının dil, kültür ve birikimlerini temsil eden iki dairenin kesişim kümesi (ortak deneyim alanı) ne kadar genişse ileti o kadar doğru anlaşılır.'),
  ('Harold Lasswell\'in 1948\'de ortaya koyduğu ünlü \'Kim, neyi, hangi kanalla, kime, hangi etkiyle söylüyor?\' formülündeki \'hangi kanalla\' sorusu iletişim araştırmalarının hangi alt dalına karşılık gelir?', 'Medya ve araç analizi', ['Denetim ve mülkiyet analizi', 'İzleyici ve hedef kitle analizi', 'Söylem ve içerik analizi'], 'Lasswell formülünde \'kim\' kontrol analizini, \'neyi\' içerik analizini, \'hangi kanalla\' araç/medya analizini, \'kime\' izleyici analizini ve \'hangi etkiyle\' etki analizini karşılar.'),
  ('Antropolog Edward T. Hall\'un kültürlerarası iletişimde insanların birbirleriyle aralarına koydukları fiziksel mesafeleri incelediği çalışma alanı aşağıdakilerden hangisidir?', 'Proksemik', ['Kronemik', 'Kinesik', 'Haptik'], 'Proksemik, insanların iletişimsel etkileşim sırasında mekânı nasıl kullandıklarını ve mahrem, kişisel, sosyal, kamusal mesafe bölgelerini nasıl düzenlediklerini inceler.'),
  ('Aynı cümlenin ses tonu, vurgu, konuşma hızı veya duraksamalar değiştirilerek söylendiğinde bambaşka imalar taşıması sözsüz iletişimin hangi boyutuyla ilgilidir?', 'Dil ötesi (paralinguistik) öğeler', ['Mekânsal dizilim kuralları', 'Yazınsal söz dizimi', 'Kültürel artefakt kullanımı'], 'Ne söylendiğinden ziyade nasıl söylendiğini belirleyen ses yüksekliği, tını, ritim, iç çekme ve tonlama gibi vokal nitelikler dil ötesi (paralanguage) kapsamındadır.'),
  ('Aristoteles\'in Retorik adlı eserinde konuşmacının kendi dürüstlüğü, uzmanlığı ve güvenilir karakteri aracılığıyla dinleyiciyi ikna etme gücünü ifade eden kavram hangisidir?', 'Ethos', ['Pathos', 'Logos', 'Kairos'], 'Aristotelesçi ikna üçgeninde ethos konuşmacının karakter ve güvenilirliğini, pathos dinleyicinin duygularını harekete geçirmeyi, logos ise mantıksal kanıtlamayı temsil eder.'),
  ('İsviçreli dilbilimci Ferdinand de Saussure\'ün göstergebilim yaklaşımında, zihindeki \'ağaç\' kavramı ile bu kavramı çağrıştıran \'a-ğ-a-ç\' ses imgesi arasındaki ilişki nasıldır?', 'Doğal bir zorunluluk taşımayan, toplumsal uzlaşıma dayalı nedensiz bir bağdır', ['Nesnenin fiziksel görünümünü birebir kopyalayan biyolojik bir yansımadır', 'Tüm dillerde aynı ses dizgesiyle ortaya çıkan evrensel bir içgüdüdür', 'Yalnızca yazılı kültürlerde geçerli olan matematiksel bir denklemdir'], 'Saussure\'e göre gösteren (ses imgesi) ile gösterilen (kavram) arasındaki bağ yansıma sözcükler dışında nedensizdir (keyfîdir) ve dil topluluğunun uzlaşısına dayanır.'),
  ('Charles Sanders Peirce\'ün gösterge üçlüsünde \'dumanın ateşi\', \'yüksek ateşin enfeksiyonu\' veya \'çamurdaki ayak izinin oradan geçen bir canlıyı\' işaret etmesi hangi gösterge türüne girer?', 'Belirti (endeks)', ['Simge (sembol)', 'Görüntüsel gösterge (ikon)', 'Üst-anlatı (mit)'], 'Peirce\'e göre belirti (index), gösteren ile nesnesi arasında doğrudan fiziksel, nedensel veya varoluşsal bir bitişiklik ilişkisi bulunan göstergedir.'),
  ('Roman Jakobson\'un iletişim ve dil işlevleri modelinde \'Alo, sesim geliyor mu?\' ya da \'Beni duyabiliyor musun?\' gibi ifadeler dilin hangi işlevini örneklendirir?', 'Kanalı kontrol etme (ilişki/fatik) işlevi', ['Şiirsel (poetik) işlev', 'Üstdil (metalinguistik) işlevi', 'Göndergesel (betimleyici) işlev'], 'Fatik (ilişki) işlev, iletişim kanalının açık ve çalışır olup olmadığını sınamak, teması başlatmak veya sürdürmek amacıyla kurulan sözceleri kapsar.'),
  ('Kültürlerarası iletişimde zamanın algılanışı, randevulara sadakat, dakik olma veya aynı anda birden fazla işle ilgilenme (polikronik/monokronik) alışkanlıklarını inceleyen sözsüz iletişim alanı hangisidir?', 'Kronemik', ['Okuletik', 'Kinesik', 'Olfaktik'], 'Kronemik (chronemics), bireylerin ve kültürlerin zamanı nasıl yapılandırdığını, bekleme sürelerinin statü ve saygı açısından ne anlama geldiğini araştırır.'),
  ('Dean Barnlund\'un dönüşümsel (transaksiyonel) iletişim modeline göre katılımcıların süreç içindeki konumu nasıldır?', 'Her katılımcı aynı anda hem mesaj gönderen kaynak hem de mesaj çözen alıcı konumundadır', ['Konuşmacı sözünü tamamen bitirene dek dinleyici hiçbir ileti gönderemez', 'İletişim yalnızca kaynağın alıcıdaki davranış değişikliğini ölçmesiyle başlar', 'Mesajın anlamı alıcının geçmişinden bağımsız olarak yalnızca sözlükte sabitlenmiştir'], 'Dönüşümsel modelde iletişim sırayla top atmak gibi değil, konuşurken aynı anda karşı tarafın yüz ifadesini okuyup tepki vermek gibi eşzamanlı ve karşılıklı bir anlam inşasıdır.'),
  ('Konuşmacının \'Şurada gördüğünüz kutu yaklaşık şu kadar büyüklükteydi\' derken elleriyle havada kutunun boyutlarını çizmesi Ekman ve Friesen\'in sınıflandırmasında hangi jest türüdür?', 'Açıklayıcı / resimleyici (illustrator)', ['Amblem (emblem)', 'Öz-uyarlayıcı (self-adaptor)', 'Örtük sansürleyici'], 'Açıklayıcılar (illustrators), sözel mesaja eşlik eden, söylenen sözleri görselleştiren, pekiştiren veya yön/boyut gösteren el ve kol hareketleridir.'),
  ('Stres altındaki bir kişinin farkında olmadan kalemle oynaması, saçıyla uğraşması veya dudaklarını ısırması sözsüz iletişim literatüründe hangi kavramla tanımlanır?', 'Uyarlayıcı (adaptör) hareketler', ['Törensel semboller', 'Kurumsal protokol işaretleri', 'Kamusal mesafe belirteçleri'], 'Uyarlayıcılar (adaptors), bireyin içsel gerginlik, kaygı veya fiziksel rahatsızlıkla başa çıkmak için çoğu kez bilinçdışı biçimde sergilediği bedensel temas ve hareketlerdir.'),
  ('El sıkışma, sırt sıvazlama, sarılma gibi dokunma davranışlarının toplumsal cinsiyet, statü ve kültürel normlara göre nasıl anlam kazandığını inceleyen alan hangisidir?', 'Haptik', ['Proksemik', 'Semiyotik', 'Sentaktik'], 'Haptik (haptics), dokunma duyusu üzerinden kurulan iletişimi ve fiziksel temasın samimiyet, teselli ya da tahakküm işlevlerini ele alır.'),
  ('Peirce\'ün gösterge sınıflandırmasında bir kişinin vesikalık fotoğrafı, coğrafi harita veya masaüstündeki yazıcı simgesi nesnesiyle kurduğu benzerlikten ötürü hangi gruba girer?', 'Görüntüsel gösterge (ikon)', ['Belirti (endeks)', 'Soyut simge (sembol)', 'Keyfî uzlaşı'], 'İkon (görüntüsel gösterge), temsil ettiği nesneye görsel veya yapısal olarak benzeyen, onun niteliklerini taklit eden göstergedir.'),
  ('Trafik ışıklarında kırmızı rengin \'dur\', yeşil rengin \'geç\' anlamına gelmesi Peirce\'ün üçlü ayrımında hangi gösterge türüne örnektir?', 'Simge (sembol)', ['İkon (görüntüsel gösterge)', 'Belirti (endeks)', 'Doğal iz'], 'Kırmızı renk ile durma eylemi arasında doğal bir benzerlik (ikon) ya da fiziksel neden-sonuç bağı (belirti) yoktur; bu ilişki toplumsal kural ve uzlaşıya dayanan bir simgedir.'),
  ('Edward T. Hall\'un kültür sınıflandırmasında mesajın büyük ölçüde fiziksel bağlamda, ortak geçmişte ve imalarda gizli olduğu, her şeyin açıkça söze dökülmediği kültürler nasıl adlandırılır?', 'Yüksek bağlamlı kültürler', ['Düşük bağlamlı kültürler', 'Atomize bireyci kültürler', 'Doğrusal sözleşme kültürleri'], 'Yüksek bağlamlı kültürlerde (ör. Japonya ve birçok Doğu/Akdeniz toplumu) sözsüz ipuçları, ilişkisel uyum ve dolaylı anlatım doğrudan sözel ifadeden daha belirleyicidir.'),
  ('Mesajların yoruma yer bırakmayacak kadar açık, doğrudan, ayrıntılı ve yazılı kurallara dayalı biçimde kodlandığı toplumlar Hall\'un kuramında hangi kavramla nitelenir?', 'Düşük bağlamlı kültürler', ['Yüksek bağlamlı kültürler', 'Sözlü gelenek kültürleri', 'Kolektivist klan kültürleri'], 'Düşük bağlamlı kültürlerde (ör. Almanya, İsviçre, Kuzey Amerika iş kültürü) anlam bağlamdan ziyade doğrudan telaffuz edilen veya yazıya geçirilen sözcüklerin kendisinde taşınır.'),
  ('Edward T. Hall\'a göre yaklaşık 120 santimetre ile 360 santimetre arasındaki aralığı kapsayan ve resmî iş görüşmeleri ya da tanışıklığı az kişilerle yapılan konuşmalarda korunan alan hangisidir?', 'Sosyal mesafe', ['Mahrem mesafe', 'Kişisel mesafe', 'Törensel mesafe'], 'Hall\'un sınıflandırmasında 0-45 cm mahrem, 45-120 cm kişisel (arkadaşlık), 120-360 cm sosyal (iş ve resmîyet), 360 cm üzeri ise kamusal mesafedir.'),
  ('Aynı sözcüğün farklı toplumsal ortamlarda kullanıcıların niyetine göre rica, alay veya tehdit olarak yorumlanmasını araştıran dilbilim ve iletişim boyutu hangisidir?', 'Edimbilim (pragmatik)', ['Sesbilgisi (fonetik)', 'Biçimbilim (morfoloji)', 'Yazım kuralları (ortografi)'], 'Pragmatik (edimbilim), dil göstergelerinin soyut sözlük anlamlarının ötesinde gerçek kullanım bağlamında konuşucu ve dinleyici açısından hangi eylemleri gerçekleştirdiğini inceler.'),
  ('Roman Jakobson\'a göre reklam sloganlarında veya emir kipli uyarı levhalarında (\'Çimlere basmayınız!\', \'Hemen başvurun!\') ağır basan dil işlevi hangisidir?', 'Alıcıyı harekete geçirme (çağrı/konatif) işlevi', ['Göndergesel (bilgi verici) işlev', 'Üstdil (tanımlayıcı) işlev', 'Fatik (kanal yoklayıcı) işlev'], 'Çağrı (konatif) işlevi doğrudan alıcıya odaklanır ve onda belirli bir davranış, tutum ya da eylem başlatmayı hedefler.'),
  ('Norbert Wiener tarafından temelleri atılan ve sistemlerin kendi çıktılarını izleyerek dengeyi koruması ilkesiyle iletişim kuramlarına \'geri bildirim\' kavramını kazandıran bilim dalı hangisidir?', 'Sibernetik', ['Paleografi', 'Heraldik', 'Numismatik'], 'Wiener\'in sibernetik kuramı, canlılarda ve makinelerde kontrol ve iletişimi inceleyerek geri besleme (feedback) mekanizmasını sosyal bilim modellerine taşımıştır.'),
  ('Bir çevirmenin yabancı dildeki atasözünü sözcüğü sözcüğüne çevirdiğinde hedef dildeki okurun bambaşka veya anlamsız bir sonuç çıkarması neden kaynaklanır?', 'Kültürel kodların ve deyimsel yananlamların diller arasında birebir örtüşmemesinden', ['Kitabın basıldığı kâğıt kalitesinin fiziksel gürültü yaratmasından', 'Okurun göz kaslarındaki fizyolojik yorgunluktan', 'Matbaa makinelerinin doğrusal sinyal üretememesinden'], 'Deyim ve atasözleri derin kültürel yananlamlar taşıdığından, bağlam ve ortak deneyim alanı gözetilmeden yapılan düz çeviriler semantik kaymaya yol açar.'),
  ('Bir konuşmacının söylediklerini pekiştiren \'Evet, kesinlikle katılıyorum\' yanıtı ile konuşmacının sesinin çok kısık olduğunu belirten \'Biraz daha yüksek sesle konuşabilir misiniz?\' uyarısı hangi açıdan ortaktır?', 'İkisinin de kaynaktan çıkan iletiye ilişkin düzeltici veya onaylayıcı geri bildirim niteliği taşıması', ['İkisinin de iletişim başlamadan önce gerçekleşen ön-kodlama aşaması olması', 'İkisinin de kitle iletişiminde eşik bekçisi tarafından sansürlenmesi', 'İkisinin de yazılı ve resmî bürokratik yazışma örneği sayılması'], 'Olumlu onaylama da kanal/anlaşılırlık düzeltmesi isteyen uyarı da alıcıdan kaynağa dönen geri bildirimdir; kaynağın sonraki mesajlarını ayarlamasını sağlar.'),
  ('Paul Watzlawick ve Palo Alto Okulu araştırmacılarının ortaya koyduğu \'İletişim kurmamak olanaksızdır\' aksiyomu ne anlatmaktadır?', 'İki kişinin birbirini algıladığı bir ortamda susmanın veya sırt çevirmenin bile bir mesaj ilettiğini', ['İnsanların uyku sırasında bile kesintisiz olarak telefon görüşmesi yapmak zorunda olduğunu', 'Yalnızca ana dili aynı olan bireylerin birbiriyle anlaşabileceğini', 'Kitle iletişim araçlarını kapatan bir kişinin toplum dışı ilan edileceğini'], 'Watzlawick\'e göre davranışın karşıtı yoktur; sessiz kalmak, konuşmayı reddetmek ya da göz temasından kaçınmak da \'seninle konuşmak istemiyorum\' mesajını taşıyan bir iletişim edimidir.'),
  ('Bir kişinin \'Hiç bilmiyorum\' cümlesini hiç kurmadan yalnızca dudak büküp iki omzunu yukarı kaldırması sözsüz iletişimin hangi işlevini gösterir?', 'Sözel ifadenin yerini alma (ikame etme)', ['Sözel ifadeyle çelişme (tekzip etme)', 'Yazılı metni arşivleme', 'Akustik yankıyı bastırma'], 'Beden hareketinin (amblem) sözcüklere hiç gerek bırakmadan başlı başına cümlenin görevini üstlenmesi ikame (yerini alma) işlevidir.'),
  ('Bir reklam afişinde lüks kol saatinin başarılı ve özgüvenli bir orkestra şefinin bileğinde gösterilmesi göstergebilimsel açıdan nasıl bir anlamlandırma stratejisidir?', 'Sanatsal saygınlık ve ustalık niteliklerini yananlam yoluyla ürüne transfer etme', ['Saatin teknik dişli mekanizması hakkında yalnızca düzanlamsal kullanım kılavuzu sunma', 'Hedef kitlenin ürünü görmesini engelleyerek fiziksel gürültü oluşturma', 'Tüketicinin marka adını hatırlamasını önlemek için entropiyi düşürme'], 'Reklam göstergebiliminde bir nesne (saat), kültürel olarak prestijli bir figürle yan yana getirilerek o figürün saygınlık yananlamıyla yüklenir.'),
  ('Bir sinema yönetmeninin karakterin yalnızlığını anlatmak için diyalog yazmak yerine onu uçsuz bucaksız boş bir ovada çok uzaktan (genel plan) görüntülemesi neyi gösterir?', 'Kamera açısı ve çerçevelemenin görsel bir kodlama dili olarak anlam ürettiğini', ['Sinema sanatında izleyiciye hiçbir ileti aktarılmadığını', 'Görüntü kalitesinin düşmesinin anlamsal gürültüyü sıfırladığını', 'Ses kuşağı olmadan kodaçımı yapılmasının biyolojik olarak imkânsız olduğunu'], 'Görsel iletişimde ölçek, ışık, renk ve kompozisyon tıpkı sözcükler gibi gösteren işlevi görerek duygusal ve kavramsal anlamlar kodlar.'),
  ('Telefonla müşteri hizmetlerini arayan bir abonenin, temsilcinin bıkkın ve alaycı ses tonundan rahatsız olup şikâyet kaydı oluşturması iletişimde hangi öğenin belirleyiciliğini kanıtlar?', 'Söylenen sözcükler nazik olsa bile dil ötesi (vokal) ipuçlarının ilişki düzeyini yönettiğini', ['Telefon görüşmelerinde yalnızca yazılı metinlerin algılanabildiğini', 'Proksemik mesafenin ses tellerini fiziksel olarak kilitlediğini', 'Müşterinin kodlama sürecinde hiçbir rol üstlenmediğini'], 'Yüz yüze görüntü olmasa dahi sesin tonu, vurgusu ve iç çekmeler (paralanguage) konuşmacının gerçek tutumunu ele vererek mesajın yorumunu değiştirir.'),
  ('C. E. Osgood ve W. Schramm\'ın dairesel modelinde her katılımcıya atfedilen üç temel işlev hangi seçenekte bir arada verilmiştir?', 'Kodlayıcı, yorumlayıcı ve kodaçıcı', ['Sansürleyici, vergilendirici ve dağıtıcı', 'Yayıncı, reklamveren ve denetçi', 'Gözlemci, arşivci ve teknisyen'], 'Osgood-Schramm dairesel şemasında iletişim özneleri sabit kaynak/alıcı kutuplarına sıkışmaz; her özne sürekli olarak kod açar, yorumlar ve yeni mesaj kodlar.'),
  ('Bir eczacının doktorun el yazısıyla yazdığı reçetedeki silik ve okunaksız ilaç adını yanlış okuması riskine karşı elektronik reçete sistemine geçilmesi hangi engeli ortadan kaldırır?', 'Kanal ve biçim kaynaklı fiziksel/mekanik gürültüyü', ['Hastanın ilacı içmeyi unutmasından doğan kronemik algıyı', 'İlaç firmaları arasındaki kurumsal halkla ilişkiler rekabetini', 'Kitle iletişim araçlarındaki gündem belirleme etkisini'], 'Silik mürekkep veya okunaksız el yazısı mesajın fiziksel/görsel sinyalini bozan bir gürültüdür; dijital standart yazı bu sinyal kaybını önler.'),
  ('Bir mesajın kodlanmasında hem görsel grafiklerin hem seslendirmenin hem de alt yazının bir arada kullanılması öğrenme ve iletişim etkinliğini neden artırır?', 'Çoklu duyusal kanalları harekete geçirerek gürültü kaynaklı anlam kaybı riskini düşürdüğü için', ['Alıcının kendi yorumlama ve düşünme kapasitesini bütünüyle devre dışı bıraktığı için', 'Mesajın doğruluğunu sorgulamayı teknik olarak olanaksız kıldığı için', 'Kaynak ile alıcı arasındaki ortak deneyim alanını sıfıra indirdiği için'], 'Birden fazla iletişim kanalının uyumlu biçimde eşzamanlı kullanımı (çok modluluk), mesajın pekişmesini ve farklı algı stillerine sahip alıcılarca kavranmasını kolaylaştırır.'),
  ('Kişilerarası iletişimde aynı odada bulunan iki kişinin cep telefonu mesajlaşma uygulaması üzerinden yazışması, iletişim sınıflandırmalarında nasıl bir melez durum oluşturur?', 'Fiziksel yakınlığa rağmen sözsüz-işitsel ipuçlarının elendiği aracılı yazılı iletişim niteliği taşır', ['Yayın kulesi gerektirmeyen geleneksel tek yönlü kitle iletişimine dönüşür', 'Kodlama ve kodaçımı basamaklarını ortadan kaldıran telepatik bir süreç yaratır', 'Geri bildirimin yalnızca yıllar sonra alınabildiği arşivsel iletişime girer'], 'Fiziksel mekân ortak olsa bile araya dijital metin arayüzünün girmesi iletişimi yüz yüze sözlü olmaktan çıkarıp aracılanmış (mediated) yazılı etkileşime çevirir.'),
  ('Edward T. Hall\'un proksemik kuramına göre asansör veya kalabalık metro vagonu gibi mahrem mesafenin zorunlu olarak ihlal edildiği ortamlarda insanların tavan numarasını izlemesi neyin göstergesidir?', 'Fiziksel yakınlığın yarattığı gerilimi göz temasını keserek telafi etme çabasının', ['Yüksek bağlamlı kültürden düşük bağlamlı kültüre kalıcı geçiş yapıldığının', 'Asansördeki herkesin birbiriyle derin bir duygusal bağ kurduğunun', 'Sözlü iletişimin kapalı mekânlarda akustik olarak imkânsızlaştığının'], 'Mahrem bölgeye yabancıların girmesi rahatsızlık doğurduğundan bireyler bedenlerini kasıp bakışlarını kaçırarak psikolojik mesafeyi koruma dengesi kurarlar.'),
  ('Empati ile sempati kavramları arasındaki temel farkı en doğru biçimde ortaya koyan ifade aşağıdakilerden hangisidir?', 'Empatide kişinin bakış açısı nesnelliği kaybetmeden anlaşılırken sempatide onun duygularına kapılıp yandaş olunur', ['Empati yalnızca klinik psikologların uygulayabildiği tıbbi bir yöntem iken sempati hukuki bir terimdir', 'Empati karşı tarafın hatalarını yüzüne vurmayı gerektirirken sempati hiç konuşmadan ortamdan uzaklaşmaktır', 'Empati yazılı iletişimde ortaya çıkarken sempati yalnızca radyo ve televizyon yayınlarında görülür'], 'Üstün Dökmen ve Carl Rogers\'ın vurguladığı üzere empati \'kendini başkasının yerine koyup onun gibi hissettikten sonra kendi konumuna dönebilmek\' iken sempati yandaşlık ve duygudaşlıkla özdeşleşmektir.'),
  ('Sınavdan düşük not aldığı için üzülen bir öğrenciye öğretmenin \'Takma kafana, dünyanın sonu değil ya, bir dahakine yaparsın, hadi gül biraz!\' demesi Thomas Gordon\'un iletişim engellerinden hangisine girer?', 'Teselli etme ve konuyu geçiştirerek duyguyu küçümseme', ['Empatik yansıtma yaparak öğrencinin içgörüsünü derinleştirme', 'Açık uçlu sorularla sorunun kök nedenini birlikte araştırma', 'Koşulsuz kabul ilkesiyle duygusal boşalıma alan açma'], 'İyi niyetli görünse de \'takma kafana\' türünden teselli kalıpları kişinin o an yaşadığı üzüntünün anlaşılmadığı ve önemsenmediği mesajını vererek iletişimi tıkar.'),
  ('Joseph Luft ve Harry Ingham tarafından geliştirilen \'Johari Penceresi\' modelinde bireyin kendisinin farkında olmadığı ancak çevresindeki insanların açıkça gözlemleyebildiği davranış ve alışkanlıklar hangi bölgede yer alır?', 'Kör alan', ['Açık (serbest) alan', 'Gizli alan', 'Bilinmeyen alan'], 'Johari Penceresi\'nde bireyin bilmediği ama başkalarının bildiği tikler, ses tonu özellikleri veya savunmacı tutumlar \'kör alan\'ı oluşturur; yapıcı geri bildirimle küçültülebilir.'),
  ('Johari Penceresi modeline göre kişilerarası güveni artırmak ve \'Açık Alan\'ı genişletmek için başvurulması gereken iki temel iletişimsel süreç hangileridir?', 'Kendini açma ve başkalarından geri bildirim alma', ['Sırları gizleme ve dedikodu kanallarını kapatma', 'Resmî yazışmaları çoğaltma ve mesafeyi koruma', 'Önyargıları pekiştirme ve seçici dinleme yapma'], 'Birey kendisini uygun ölçüde açtıkça \'gizli alan\' daralır; çevresinden samimi geri bildirim kabul ettikçe \'kör alan\' daralır ve böylece \'açık alan\' büyür.'),
  ('İlk tanışmada çok şık giyimli ve düzgün diksiyonlu bir adayın mesleki teknik bilgisinin ve iş ahlakının da kusursuz olacağının varsayılması algısal engellerden hangisiyle açıklanır?', 'Hale (ayla) etkisi', ['Sonralık etkisi', 'Karşıtlık yanılgısı', 'Suskunluk sarmalı'], 'Edward Thorndike\'ın tanımladığı hale etkisi, kişinin tek bir olumlu özelliğinden yola çıkarak onun diğer tüm nitelikleri hakkında aşırı olumlu genelleme yapılmasıdır.'),
  ('Muhasebe departmanında çalışan bir uzmanın kendi müdürünü aşmaya gerek kalmadan doğrudan insan kaynakları müdürüyle maaş bordrosu yazılımı hakkında görüşmesi ne tür bir iletişimdir?', 'Çapraz (diyagonal) iletişim', ['Dikey otoriter iletişim', 'Kapalı devre tek yönlü iletişim', 'Kitle iletişim kampanyası'], 'Farklı departmanlarda ve farklı hiyerarşik düzeylerde bulunan çalışanların zaman kazanmak ve iş akışını hızlandırmak için doğrudan kurdukları temas çapraz iletişimdir.'),
  ('Kurumlarda resmî duyuru kanalları yetersiz kaldığında ve belirsizlik arttığında koridor sohbetleri ve öğle yemeği buluşmaları üzerinden hızla yayılan biçimsel olmayan iletişim ağına literatürde ne ad verilir?', 'Söylenti / fısıltı ağı', ['Kurumsal intranet bülteni', 'Hiyerarşik protokol zinciri', 'Kamusal aydınlatma platformu'], 'Biçimsel olmayan (informal) iletişim ağı yani \'üzüm asması\' (grapevine), kriz ve belirsizlik dönemlerinde resmî kanalların boşluğunu doldurarak çok hızlı yayılır.'),
  ('Grunig ve Hunt\'ın sınıflandırmasında 19. yüzyılda P. T. Barnum ile özdeşleşen, abartılı şovlarla ne pahasına olursa olsun basında yer almayı hedefleyen ve doğruluğu ikincil gören halkla ilişkiler modeli hangisidir?', 'Basın ajanslığı / tanıtım modeli', ['İki yönlü simetrik müzakere modeli', 'Kurumsal sosyal sorumluluk modeli', 'Paydaş katılımlı yönetişim modeli'], 'Basın ajanslığı modeli tek yönlüdür; temel amacı dikkat çekmek ve propaganda yoluyla görünürlük sağlamaktır, bilimsel doğruluk kaygısı taşımaz.'),
  ('Kurumsal iletişim literatüründe \'kurumsal imaj\' ile \'kurumsal itibar\' arasındaki temel fark aşağıdakilerden hangisidir?', 'İmaj kısa sürede reklam ve tasarımla oluşturulabilen anlık izlenim iken itibar yıllar içindeki tutarlı davranışlarla kazanılan kalıcı güvendir', ['İmaj yalnızca şirket çalışanlarının maaş düzeyini gösterirken itibar yalnızca fabrikanın mimari yüksekliğini ifade eder', 'İmaj devlet kurumlarına özgü resmî bir kavram iken itibar yalnızca küçük esnaf işletmelerinde görülür', 'İmaj finansal bilançolarda yer alan maddi bir borç kalemi iken itibar reklam ajanslarının kullandığı bir yazı tipidir'], 'Kurumsal imaj görsel kimlik ve kampanyalarla görece hızlı şekillendirilebilir; kurumsal itibar ise tüm paydaşların uzun yıllara yayılan deneyim ve etik değerlendirmelerinin toplamıdır.'),
  ('Marshall Rosenberg\'in \'Şiddetsiz İletişim\' (NVC) modelini oluşturan dört ardışık bileşen hangi seçenekte doğru sırayla verilmiştir?', 'Yargısız gözlem, duygu, ihtiyaç ve somut rica', ['Teşhis, ahlaki yargı, ödüllendirme ve yaptırım', 'Övgü, eleştiri, savunma ve uzlaşma tutanağı', 'Varsayım, genelleme, tavsiye ve son uyarı'], 'Rosenberg\'in Şiddetsiz İletişim süreci; olan biteni değerlendirme katmadan gözlemlemek, hissedilen duyguyu adlandırmak, bu duygunun ardındaki ihtiyacı fark etmek ve açık bir ricada bulunmaktan oluşur.'),
  ('Psikiyatrist Eric Berne\'ün \'Transaksiyonel Analiz\' kuramında bireyin olguları mantık süzgecinden geçiren, önyargısız veri toplayan ve \'şimdi ve burada\' gerçekliğine göre problem çözen benlik durumu hangisidir?', 'Yetişkin benlik durumu', ['Eleştirel Ebeveyn benlik durumu', 'Doğal Çocuk benlik durumu', 'Uygulu Çocuk benlik durumu'], 'Berne\'e göre Ebeveyn benlik durumu öğrenilmiş kuralları ve yargıları, Çocuk benlik durumu dürtü ve duyguları, Yetişkin benlik durumu ise nesnel veri işlemeyi ve akılcı değerlendirmeyi temsil eder.'),
  ('Sosyolog Erving Goffman\'ın \'Günlük Yaşamda Benliğin Sunumu\' adlı eserinde garsonların müşterilere güler yüzlü ve resmi davrandığı restoran salonu ile kendi aralarında rahatça dertleştikleri mutfak sırasıyla hangi kavramlarla açıklanır?', 'Ön bölge (sahne önü) ve arka bölge', ['Kamusal alan ve sivil toplum', 'Merkez çevre ve yarı-çevre', 'Açık pencere ve bilinmeyen pencere'], 'Goffman dramaturjik yaklaşımında toplumsal yaşamı tiyatroya benzetir; ön bölgede toplumsal rollere uygun izlenim yönetimi yapılırken arka bölgede resmi maskeler çıkarılıp dinlenilir.'),
  ('Rahim ve Thomas-Kilmann çatışma yönetimi modellerinde her iki tarafın da temel ihtiyaçlarını gözeten, yaratıcı seçenekler üreterek \'kazan-kazan\' çözümüne ulaşmayı hedefleyen strateji hangisidir?', 'Tümleştirme (işbirliği / problem çözme)', ['Kaçınma (geri çekilme)', 'Hükmetme (rekabet)', 'Uyma (ödün verme)'], 'Tümleştirme stilinde hem kendi çıkarına hem karşı tarafın çıkarına verilen önem yüksektir; yüzeysel pazarlık yerine sorunun köküne inen ortak çözüm üretilir.'),
  ('Etkin dinleme sürecinde dinleyicinin \'Yani iş yükünün son ayda iki katına çıkması ve destek alamamak seni tükenmiş hissettiriyor, doğru mu anladım?\' diyerek konuşmacının mesajını kendi cümleleriyle geri vermesi hangi tekniktir?', 'Yeniden ifade etme ve duygu yansıtma', ['Konuyu kendi başından geçen bir anıya çekerek odak kaydırma', 'Ahlak dersi vererek konuşmacının hatalarını sıralama', 'Kapalı uçlu sorgulamayla konuşmacıyı köşeye sıkıştırma'], 'Carl Rogers\'ın yansıtmacı/etkin dinleme tekniğinde mesajın içerik ve duygu özeti kendi sözcüklerimizle karşı tarafa sunularak anlaşıldığı teyit edilir.'),
  ('Halkla ilişkiler ile reklamcılık faaliyetlerini karşılaştıran aşağıdaki ifadelerden hangisi doğrudur?', 'Reklam satın alınmış medya alanında denetimli satış mesajı sunarken halkla ilişkiler editoryal güven ve uzun vadeli karşılıklı anlayış kazanmaya odaklanır', ['Reklam tamamen ücretsiz kamu hizmeti iken halkla ilişkiler yalnızca televizyon kuşaklarında saniye bazında para ödenerek yayınlanır', 'Reklam yalnızca kurum içi çalışanlara yönelik iken halkla ilişkiler yalnızca yabancı ülke hükümetlerini hedefler', 'Reklamda geri bildirim toplamak yasakken halkla ilişkilerde basın bülteni yazmak meslek etiğine aykırıdır'], 'Reklam \'ödenmiş medya\' (paid media) üzerinden ticari ikna ve marka tutumu hedefler; halkla ilişkiler ise \'kazanılmış medya\' (earned media) ve paydaş diyaloğu üzerinden itibar yönetir.'),
  ('Bir kişinin iş yerinde amirinden işittiği haksız azara ses çıkaramayıp akşam eve geldiğinde hiçbir suçu olmayan küçük kardeşine bağırması iletişim çatışmalarında hangi psikolojik savunma düzeneğidir?', 'Yön değiştirme (yer değiştirme)', ['Yüceltme (sublimasyon)', 'Özgeci empati', 'Bilişsel çerçeveleme'], 'Asıl hedefe yöneltilmesi tehlikeli veya riskli görülen öfke duygusunun daha güçsüz ya da güvenli başka bir kişiye/nesneye boşaltılması yer değiştirme (displacement) mekanizmasıdır.'),
  ('Derdini anlatan arkadaşına \'Aynı olay geçen yıl benim de başıma geldi, ben günlerce uyuyamamıştım, bak sana benim başıma geleni anlatayım...\' diyerek sözü devralan kişi Üstün Dökmen\'in sınıflandırmasında hangi basamakta kalmıştır?', 'Ben basamağı', ['Sen basamağı', 'Onlar basamağı', 'Bütüncül aşama'], 'Ben basamağında tepki veren kişi karşı tarafın acısına değinse de odağı hızla kendi yaşantısına kaydırarak dert sahibini dinleyici konumuna düşürür.'),
  ('Örgüt içi iletişimde üst yönetime rapor sunulurken kötü haberlerin yumuşatılması veya gizlenmesi eğilimine (\'yukarıya doğru filtreleme\') yol açan başlıca kurumsal etken nedir?', 'Hataları cezalandıran otoriter yönetim iklimi ve çalışanların psikolojik güvenlikten yoksun olması', ['Şirket binasında fiber optik internet bağlantısının yüksek hızda çalışması', 'Yatay departmanlar arasında düzenli koordinasyon toplantılarının yapılması', 'Kurumsal kimlik kılavuzunda açık renkli logoların tercih edilmesi'], 'Astlar olumsuz veriyi bildirdiklerinde suçlanacaklarından veya terfi şanslarını kaybedeceklerinden korkarlarsa aşağıdan yukarıya dikey iletişim çarpıtılır ve üst yönetim sahadaki gerçeklerden kopar.'),
  ('Çatışma çözme stillerinden \'kaçınma\' (geri çekilme) stratejisinin geçici olarak işlevsel ve yerinde sayılabileceği durum aşağıdakilerden hangisidir?', 'Tarafların aşırı öfkeli olduğu ve sağlıklı konuşabilmek için sakinleşme süresine ihtiyaç duyulduğu anlar', ['Fabrikada acil müdahale gerektiren hayati bir iş güvenliği tehlikesinin belirdiği dakikalar', 'Uzun vadeli şirket birleşmesi sözleşmesinin temel ilkelerinin karara bağlandığı son oturum', 'Ekip üyelerinin yaratıcı fikirlerini birleştirerek yeni bir patent geliştirmeye çalıştığı atölye'], 'Kaçınma kronikleştiğinde sorunları büyütür; ancak önemsiz konularda veya duygusal tansiyonun çok yükselip yıkıcı olabileceği anlarda soğuma süresi kazanmak için bilinçli biçimde kullanılabilir.'),
  ('Bir konuşmada sürekli \'Sen hep böylesin\', \'Asla beni anlamıyorsun\', \'Hiçbir zaman yardım etmezsin\' gibi mutlaklaştırıcı zarflar kullanmak kişilerarası iletişimi neden zedeler?', 'Tekil bir davranışı tüm geçmişe genelleştirerek karşı tarafta haksızlığa uğradığı duygusu ve direnç yarattığı için', ['Konuşmanın dilbilgisel özne-yüklem uyumunu bozarak ses tellerini yorduğu için', 'Muhatabın sorunu çok hızlı çözmesine ve tartışmanın hemen bitmesine yol açtığı için', 'Yalnızca resmi mahkeme tutanaklarında kullanılması gereken hukuki terimler olduğu için'], '\'Hep, asla, hiçbir zaman\' gibi aşırı genellemeler olgusal gerçeği çarpıtır; muhatap asıl sorunu düşünmek yerine istisnaları kanıtlayarak kendini savunmaya odaklanır.'),
  ('Bir şirketin ürettiği deterjanın doğaya zararlı kimyasallar içermesine rağmen ambalajını yeşil yaprak görselleriyle süsleyip \'doğa dostu\' sloganıyla halkla ilişkiler kampanyası yürütmesi eleştirel literatürde nasıl adlandırılır?', 'Yeşil aklama', ['İki yönlü simetrik diyalog', 'Şeffaf sürdürülebilirlik raporlaması', 'Kurum içi yatay entegrasyon'], 'Yeşil aklama, bir kurumun gerçek üretim süreçlerinde çevresel zararı sürdürürken yanıltıcı halkla ilişkiler ve reklam söylemleriyle çevreci bir imaj çizmeye çalışmasıdır.'),
  ('Sivil toplum kuruluşlarının veya meslek birliklerinin parlamento üyelerine ve karar alıcılara uzmanlık raporları sunarak yasa tasarılarını meşru yollarla etkilemeye çalışması hangi kurumsal iletişim etkinliğidir?', 'Lobicilik', ['Doğrudan perakende pazarlama', 'Kişi içi öz-denetim', 'Suskunluk sarmalı üretimi'], 'Lobicilik, kamu politikalarını ve yasama süreçlerini temsil edilen grubun veya kurumun görüşleri doğrultusunda bilgilendirme ve ikna yoluyla yönlendirme faaliyetidir.'),
  ('Carl Rogers\'ın birey merkezli iletişim anlayışında sağlıklı ve iyileştirici bir kişilerarası ilişkinin kurulabilmesi için aranan üç temel koşul hangileridir?', 'Empati, koşulsuz olumlu kabul ve saydamlık', ['Otorite, maddi ödüllendirme ve sürekli öğüt verme', 'Mesafeli resmiyet, sorgulama ve kusurları yüzleştirme', 'Rekabet, stratejik gizlilik ve duygusal nötrlük'], 'Rogers\'a göre karşımızdaki kişiyi yargılamadan değer vermek (koşulsuz kabul), maskesiz ve samimi olmak (saydamlık/tutarlılık) ve empatik anlayış göstermek yapıcı iletişimin temelidir.'),
  ('Çok uluslu bir şirkette farklı ülkelerden gelen mühendislerin ortak proje yürütürken kendi kültürlerinin normlarını tek doğru ve üstün ölçü kabul edip diğer çalışma biçimlerini küçümsemesi hangi iletişim engelidir?', 'Etnosentrizm', ['Kültürel görelilik', 'Yöndeşik medya okuryazarlığı', 'Simetrik paydaş katılımı'], 'Etnosentrizm, bireyin kendi etnik veya ulusal kültürünü merkeze koyarak diğer tüm kültürleri kendi ölçütleriyle yargılayıp aşağı görmesi eğilimidir; kültürlerarası iletişimi felce uğratır.'),
  ('Bir belediyenin yeni metro hattı inşaatına başlamadan önce mahalle sakinleriyle halk toplantıları düzenleyip esnafın çekincelerini dinlemesi ve şantiye girişlerini bu önerilere göre revize etmesi neyi gösterir?', 'Paydaş katılımına dayalı proaktif ve iki yönlü simetrik halkla ilişkiler anlayışını', ['Kriz patlak verdikten sonra başvurulan savunmacı inkâr stratejisini', 'Kamuoyunu yanıltmayı hedefleyen tek yönlü propaganda kampanyasını', 'Örgüt içi biçimsel olmayan söylenti ağının denetimsiz bırakılmasını'], 'Sorun çıkmadan önce (proaktif) etkilenen paydaşları dinleyip projede somut düzenleme yapmak iki yönlü simetrik halkla ilişkilerin örnek uygulamasıdır.'),
  ('Kişilerarası iletişimde bir arkadaşının üzüntüsünü dinlerken \'Bence hemen istifa etmelisin, ben olsam bir dakika durmam!\' şeklinde konuşmak neden iletişim engeli sayılır?', 'Hazır çözüm ve öğüt dayatarak kişinin kendi koşullarını değerlendirme özerkliğini gölgelediği için', ['Açık uçlu soru sorarak konuşmacıyı gereğinden fazla düşündürdüğü için', 'Ben dili kurallarına eksiksiz uyarak duygusal yakınlığı artırdığı için', 'Sessiz kalarak karşı tarafa geniş bir anlatım boşluğu bıraktığı için'], 'Talep edilmeden verilen kesin öğüt ve yönlendirmeler, dert sahibinin kendi çözüm üretme kapasitesine güvenilmediği mesajını verir ve sorumluluk dengesini bozar.'),
  ('Leon Festinger\'in \'Bilişsel Çelişki (Uyumsuzluk) Kuramı\'na göre sigaranın akciğer kanserine yol açtığını bilen bir tiryakinin bu içsel huzursuzluğu azaltmak için \'Benim dedem doksan yaşına kadar içti, hiçbir şey olmadı\' demesi nasıl bir iletişim ve düşünce tepkisidir?', 'Davranışıyla çelişen bilginin önemini küçültüp rasyonelleştirici yeni inançlar üreterek zihinsel denge arama', ['Bilimsel verileri tam olarak benimseyip alışkanlığını anında ve kalıcı biçimde terk etme', 'Karşıt görüşlü tıp dergilerine abone olarak kendi inancını çürütmeye çalışma', 'İletişim sürecindeki tüm fiziksel gürültü kaynaklarını teknik cihazlarla ölçme'], 'Festinger\'e göre birey birbiriyle çelişen iki biliş (inanç ve davranış) yaşadığında rahatsızlık duyar; davranışı değiştirmek zor geldiğinde seçici algı ve bahanelerle çelişkiyi hafifletmeye yönelir.'),
  ('Süpermarkette acelesi olan ve deterjan kimyasıyla hiç ilgilenmeyen bir tüketicinin yalnızca sevdiği bir dizi oyuncusunun fotoğrafı bulunduğu için o markayı sepete atması Petty ve Cacioppo\'nun modelinde hangi ikna yoludur?', 'Çevresel (periferik) ikna yolu', ['Merkezi (analitik) ikna yolu', 'Diyalektik müzakere yolu', 'Simgesel direniş yolu'], 'Konuya yönelik derin düşünme motivasyonu düşük olduğunda alıcılar argümanların bilimsel kanıtları yerine kaynağın sevimliliği, müzik veya slogan kafiyesi gibi çevresel ipuçlarıyla ikna olurlar.'),
  ('Örgütsel iletişimde açık kapı politikası izlediğini ilan eden bir yöneticinin, odasına sorun anlatmaya gelen çalışanların sözünü sürekli telefonla bölmesi ve hiçbir öneriyi uygulamaya koymaması neye yol açar?', 'Söylem-eylem tutarsızlığı nedeniyle kurumsal güvenin aşınmasına ve göstermelik katılım algısına', ['Aşağıdan yukarıya dikey iletişim kanallarının her zamankinden daha verimli çalışmasına', 'Biçimsel olmayan dedikodu ve söylenti ağlarının kurum içinde tamamen sona ermesine', 'Çalışanların Johari Penceresi\'ndeki açık alanlarının hızla genişlemesine'], 'Kurumsal iletişimde ilan edilen politikalar yönetici davranışlarıyla desteklenmediğinde çalışanlarda sinizm (kuşkuculuk) oluşur ve geri bildirim kanalları kapanır.'),
  ('Sözlü bir tartışma sırasında konuşmacının asıl konudaki zayıf kanıtını gizlemek için muhatabının geçmişteki ilgisiz bir hatasını gündeme getirerek kişiliğine saldırması mantık ve iletişimde nasıl adlandırılır?', 'Kişiliğe saldırı yanılgısı', ['Tümevarımsal kanıtlama yöntemi', 'İki yönlü simetrik müzakere', 'Empatik duygu yansıtması'], 'Ad hominem safsatası, öne sürülen görüşün doğruluğunu tartışmak yerine o görüşü savunan kişinin karakterine, dış görünüşüne veya geçmişine saldırarak konuyu saptırmaktır.'),
  ('Bir kurumun tüm pazarlama, reklam, halkla ilişkiler, dijital medya ve satış geliştirme mesajlarını birbiriyle çelişmeyecek biçimde tek bir stratejik ses ve görsel bütünlükle yönetmesi hangi kavramla ifade edilir?', 'Bütünleşik pazarlama iletişimi', ['Dağınık departman özerkliği', 'Kitle toplumu yabancılaşması', 'Sihirli mermi propagandası'], 'Don Schultz gibi isimlerce geliştirilen Bütünleşik Pazarlama İletişimi (IMC), farklı kanallardan çıkan kurumsal mesajların tüketici zihninde tutarlı ve sinerjik bir marka algısı yaratmasını hedefler.'),
  ('1968 ABD Başkanlık seçimlerinde Chapel Hill seçmenleri üzerinde yapılan klasik araştırma hangi iletişim kuramının temelini atmıştır?', 'Gündem Belirleme', ['Suskunluk Sarmalı', 'Ekme', 'Bilgi Gediği Hipotezi'], 'McCombs ve Shaw, Chapel Hill çalışmasıyla kararsız seçmenlerin önemli gördüğü konularla yerel/ulusal medyanın öne çıkardığı başlıklar arasında yüksek korelasyon saptamıştır.'),
  ('Bir gazetenin ekonomik krizi sadece döviz kuru tablolarıyla değil, "sorumsuz tüketim alışkanlıklarının bedeli" başlığıyla sunması hangi kuramsal mekanizmaya örnektir?', 'Çerçeveleme (Framing)', ['Eşik Bekçiliği (Gatekeeping)', 'İki Aşamalı Akış', 'Enformasyon Kuramı'], 'Çerçeveleme, bir olgunun belirli yönlerini seçip öne çıkararak sorunun tanımını, nedensel yorumunu ve ahlaki değerlendirmesini yönlendirme sürecidir.'),
  ('Suskunluk Sarmalı kuramını geliştirerek kamuoyunu "toplumsal denetim ve bütünleşme sağlayan görünmez bir mahkeme" olarak nitelendiren Alman siyaset bilimci kimdir?', 'Elisabeth Noelle-Neumann', ['Jürgen Habermas', 'Paul Lazarsfeld', 'Marshall McLuhan'], 'Alman araştırmacı Elisabeth Noelle-Neumann, seçmen davranışları üzerindeki araştırmalarından hareketle Suskunluk Sarmalı (Spiral of Silence) kuramını formüle etmiştir.'),
  ('George Gerbner\'in Ekme Kuramı bağlamında geliştirdiği ve yoğun televizyon izleyicilerinin yabancılara karşı duyduğu aşırı güvensizlik ile korkuyu anlatan kavram hangisidir?', 'Acımasız Dünya Sendromu', ['Panik Odası Etkisi', 'Toplumsal Yabancılaşma Sarmalı', 'Bilişsel Çarpıtma Sendromu'], '"Acımasız Dünya Sendromu" (Mean World Syndrome), televizyondaki yoğun suç ve şiddet temsillerine maruz kalan izleyicilerin dünyayı olduğundan daha tekinsiz sanmasıdır.'),
  ('Farklı gelir, eğitim ve siyasi görüşten gelen yoğun televizyon izleyicilerinin, zamanla ortak ve homojen bir dünya görüşünde buluşmasını Ekme Kuramı hangi kavramla açıklar?', 'Anaakımlaştırma', ['Kültürel difüzyon', 'Toplumsal kutuplaşma', 'Eşik bekçiliği süreci'], 'Anaakımlaştırma (mainstreaming), farklı toplumsal gruplardan gelen ağır izleyicilerin televizyonun sunduğu ortak sembolik ortama çekilerek görüş farklılıklarının törpülenmesidir.'),
  ('Medyanın bir konuyu sürekli gündemde tutarak izleyicilerin siyasi liderleri değerlendirirken o konuyu temel ölçüt olarak kullanmasına yol açması hangi kavramla ifade edilir?', 'Öne Çıkarma', ['Suskunluk Sarmalı', 'Kullanımlar ve Doyumlar', 'İki Aşamalı Akış'], 'Öne çıkarma (priming/hazırlama), gündem belirlemenin bir uzantısı olarak medyanın vurguladığı konuların, halkın lider performansını yargılama standartlarını şekillendirmesidir.'),
  ('Sosyolog Erving Goffman\'ın bireylerin günlük yaşam deneyimlerini anlamlandırmak için kullandığı "yorumlama şemaları"nı ele aldığı ve medya çalışmalarına ilham veren eseri hangisidir?', 'Çerçeve Analizi', ['Kamusal Alanın Yapısal Dönüşümü', 'Medyayı Anlamak', 'Rızanın İmalatı'], 'Erving Goffman\'ın 1974 tarihli "Frame Analysis" (Çerçeve Analizi) adlı eseri, sosyal bilimler ve iletişimde çerçeveleme kuramının sosyolojik temelini oluşturmuştur.'),
  ('Shanto Iyengar\'ın haber çerçeveleri sınıflandırmasına göre, yoksulluğu yapısal ekonomik veriler yerine yalnızca sokakta kalan tek bir ailenin dramıyla anlatan haber hangi çerçeveyi kullanır?', 'Epizodik (Olaysal) çerçeve', ['Tematik (Bütüncül) çerçeve', 'Kurumsal denetim çerçevesi', 'Stratejik rekabet çerçevesi'], 'Iyengar\'a göre epizodik çerçeveler somut bireysel vakalara odaklanıp sorumluluğu bireye yüklerken, tematik çerçeveler genel bağlamı ve toplumsal/politik sorumluluğu gösterir.'),
  ('Paul Lazarsfeld ve arkadaşlarının 1940 ABD seçimlerinde Erie İlçesi\'nde yürüttüğü "Halkın Seçimi" (The People\'s Choice) araştırması hangi kuramın doğuşuna zemin hazırlamıştır?', 'İki Aşamalı Akış Kuramı', ['Suskunluk Sarmalı Kuramı', 'Gündem Belirleme Kuramı', 'Ekme (Kültivasyon) Kuramı'], 'Lazarsfeld ve ekibi, medya mesajlarının seçmenleri doğrudan değiştirmekten çok "kanaat önderleri" aracılığıyla dolaylı ve sınırlı biçimde etkilediğini keşfetmiştir.'),
  ('"Medya insanlara ne yapıyor?" sorusu yerine "İnsanlar medyayla ne yapıyor?" sorusunu merkeze alarak aktif izleyici kavramını öne çıkaran kuram hangisidir?', 'Kullanımlar ve Doyumlar', ['Ekme Kuramı', 'Kültür Endüstrisi', 'Rızanın İmalatı'], 'Elihu Katz, Jay Blumler ve Michael Gurevitch\'in katkılarıyla gelişen Kullanımlar ve Doyumlar yaklaşımı, bireylerin psikolojik ve sosyal ihtiyaçlarını doyurmak için medyayı bilinçli seçtiğini savunur.'),
  ('Bir bireyin "Reklamlar ve yanıltıcı haberler beni hiç etkilemez ama toplumdaki diğer saf insanları kolayca kandırır" şeklinde düşünmesi hangi kuramla açıklanır?', 'Üçüncü Kişi Etkisi', ['Bilişsel Uyumsuzluk', 'Suskunluk Sarmalı', 'Anaakımlaştırma'], 'W. Phillips Davison\'ın 1983\'te tanımladığı Üçüncü Kişi Etkisi (Third-Person Effect), insanların medyanın başkaları üzerindeki etkisini abartırken kendileri üzerindeki etkisini küçümsemesidir.'),
  ('1938 yılında H. G. Wells\'in "Dünyalar Savaşı" romanını radyo tiyatrosu olarak haber bülteni formatında sunup ABD\'de kitlesel paniğe yol açan yönetmen kimdir?', 'Orson Welles', ['Edward R. Murrow', 'Walter Cronkite', 'Marshall McLuhan'], 'Orson Welles\'in Cadılar Bayramı arifesinde sunduğu radyo yayını, gerçek bir Marslı istilası sanılarak medya etkileri tarihinde kritik vaka analizlerinden biri olmuştur.'),
  ('Edward S. Herman ve Noam Chomsky\'nin 1988\'de yayımladıkları "Rızanın İmalatı" adlı eserde kitle medyasının haber üretimini açıklamak için kurdukları modelin adı nedir?', 'Propaganda Modeli', ['Kamusal Alan Modeli', 'Çoklu Akış Modeli', 'Ağ Toplumu Modeli'], 'Herman ve Chomsky\'nin Propaganda Modeli; mülkiyet, reklam, haber kaynakları, tepki üretimi (flak) ve ideolojik süzgeçlerden geçen haberlerin egemen çıkarları koruduğunu savunur.'),
  ('Habermas\'a göre 18. ve 19. yüzyıllarda eleştirel tartışma zemini olan kamusal alanın yozlaşarak "yeniden feodalleşmesine" yol açan temel etken nedir?', 'Medyanın ticarileşmesi ve halkla ilişkiler/reklamcılık endüstrisinin yükselişi', ['Okuryazarlık oranlarının toplumun alt kesimlerinde hızla yaygınlaşması', 'Yerel gazetelerin kapanarak yerini ulusal devlet arşivlerine bırakması', 'Üniversitelerde iletişim ve sosyoloji bölümlerinin açılmaya başlaması'], 'Habermas, kitle basınının reklam gelirlerine bağımlı ticari işletmelere dönüşmesiyle yurttaşların "tartışan kamu"dan "tüketen kitle"ye indirgendiğini savunur.'),
  ('Galtung ve Ruge\'nin haber değerleri kuramına göre, küçük çaplı bir sel felaketinin görmezden gelinirken büyük yıkım yaratan bir depremin manşete taşınması hangi ölçütü örneklendirir?', 'Büyüklük eşiği (Threshold)', ['Kişiselleştirme (Personalization)', 'Ünsiyet / Tanıdıklık (Consonance)', 'Süreklilik (Continuity)'], 'Büyüklük eşiği (threshold), bir olayın medya kapısından geçebilmesi için etkilediği insan sayısı veya şiddet bakımından belirli bir yoğunluk sınırını aşması gerektiğini ifade eder.'),
  ('Bir televizyon kanalının asgari ücret zammını "ekonomide büyük müjde" olarak kodladığı haberi izleyen bir işçinin, "enflasyon karşısında alım gücümüz yine eridi" diyerek mesajı reddetmesi Stuart Hall\'a göre nedir?', 'Muhalif okuma', ['Egemen okuma', 'Pasif alımlama', 'Bilişsel uyumlama'], 'Muhalif (oppositional) okumada alıcı, metnin düz ve yan anlamını anlar ancak mesajı kendi alternatif referans çerçevesi içinde tamamen zıt bir biçimde yeniden yorumlar.'),
  ('Psikolog Leon Festinger\'in geliştirdiği ve bireylerin mevcut inançlarıyla çelişen haberlerden kaçınıp kendi görüşlerini destekleyen medyaya yönelmesini açıklayan kuram hangisidir?', 'Bilişsel Uyumsuzluk Kuramı', ['Sihirli Mermi Kuramı', 'Gündem Belirleme Kuramı', 'Bilgi Gediği Kuramı'], 'Festinger\'in Bilişsel Uyumsuzluk (Cognitive Dissonance) kuramına göre bireyler zihinsel huzursuzluğu azaltmak için "seçici maruz kalma" davranışı göstererek inançlarıyla uyumlu yayınları seçer.'),
  ('Aynı tartışma programını izleyen iki rakip parti taraftarının, program bittiğinde kendi adaylarının çok daha başarılı olduğu sonucunu çıkarıp yalnızca kendi adaylarının güçlü kanıtlarını hatırlaması neyi gösterir?', 'Seçici algı ve seçici hatırlama', ['Üçüncü kişi etkisi ve sansür', 'Suskunluk sarmalı ve dışlanma', 'Gündem belirleme ve eşik bekçiliği'], 'İnsanlar mesajları kendi tutumlarına göre yorumlar (seçici algı) ve zihinlerinde kendi görüşlerini destekleyen ayrıntıları daha uzun süre tutar (seçici hatırlama).'),
  ('Bir siyasi aktörün veya kurumun, kamuoyunun dikkatini skandallardan uzaklaştırmak amacıyla yapay krizler ya da sansasyonel yan başlıklar üretmesi habercilikte nasıl adlandırılır?', 'Gündem saptırma', ['Tematik çerçeveleme uygulaması', 'Yurttaş gazeteciliği pratiği', 'Araştırmacı gazetecilik faaliyeti'], 'Gündem saptırma, asıl tartışılması gereken yapısal sorunların üstünü örtmek için medyanın dikkatini tali ve sansasyonel konulara çekme stratejisidir.'),
  ('Geleneksel haber yazımında en önemli ve can alıcı bilginin en başta, ayrıntıların ise önem sırasına göre azalarak alt paragraflarda verildiği tekniğe ne ad verilir?', 'Ters piramit tekniği', ['Kronolojik öyküleme', 'Dörtgen haber kuralı', 'Huni akış modeli'], 'Telgraf haberciliği döneminde hat kopmalarına karşı en kritik bilginin ilk cümlede (flaş/giriş) iletilmesi ihtiyacından doğan bu yönteme ters piramit tekniği denir.'),
  ('Fred Siebert, Theodore Peterson ve Wilbur Schramm\'ın 1956 tarihli klasik "Basının Dört Kuramı" eserinde, medyanın özgür olmasının yanı sıra topluma karşı ahlaki yükümlülük taşıdığını savunan kuram hangisidir?', 'Sosyal Sorumluluk Kuramı', ['Otoriter Basın Kuramı', 'Liberteryen (Özgürlükçü) Kuram', 'Sovyet Komünist Basın Kuramı'], '1947 Hutchins Komisyonu raporuna dayanan Sosyal Sorumluluk Kuramı, sınırsız ticari basın özgürlüğünün suistimallerine karşı doğru, dengeli ve çoğulcu habercilik ödevini getirmiştir.'),
  ('Bir çevre felaketini araştıran gazetecinin sadece şirket sözcüsünün basın bültenini yayımlamakla yetinmeyip bağımsız laboratuvar raporlarını ve bölge halkının tanıklıklarını habere eklemesi hangi ilkeyi karşılar?', 'Çok seslilik ve çapraz doğrulama', ['Epizodik çerçeveleme yöntemi', 'Suskunluk sarmalı oluşturma', 'Öne çıkarma (priming) stratejisi'], 'Tek kaynağa (özellikle çıkar sahibi kurumsal kaynağa) bağlı kalmadan bağımsız verilerle ve etkilenen taraflarla çapraz kontrol yapmak gazetecilikte nesnelliğin ve doğruluğun temelidir.'),
  ('Büyük ve prestijli ulusal/uluslararası haber kuruluşlarının manşete taşıdığı konuların, daha küçük yerel gazeteler ve televizyon bültenleri tarafından taklit edilerek gündeme alınmasına ne denir?', 'Medyalararası gündem belirleme', ['İki aşamalı iletişim akışı', 'Bilişsel uyumsuzluk çözümü', 'Tersine suskunluk sarmalı'], 'Maxwell McCombs\'un tanımladığı medyalararası gündem belirleme (intermedia agenda setting), elit haber kuruluşlarının diğer medya organları için referans ve eşik bekçisi işlevi görmesidir.'),
  ('Marshall McLuhan\'ın elektronik iletişim araçlarının mesafeleri ortadan kaldırarak dünyadaki insanları anlık bilgi akışıyla birbirine bağladığını anlatmak için türettiği kavram hangisidir?', 'Küresel Köy', ['Ağ Toplumu', 'Enformasyon Çağı', 'Gözetim Kapitalizmi'], 'McLuhan, elektronik medyanın görsel-işitsel eşzamanlılığı sayesinde dünyanın tıpkı geleneksel bir köy gibi herkesin her şeyden anında haberdar olduğu "Küresel Köy"e (Global Village) dönüştüğünü belirtmiştir.'),
  ('Bir televizyon tartışmasında sunucunun bilimsel konsensüs olan bir konuda, %99\'luk uzman görüşünün karşısına %1\'lik marjinal bir komplo teorisyenini çıkarıp ikisine eşit süre vermesi hangi gazetecilik yanılgısıdır?', 'Sahte denge', ['Tematik çerçeveleme', 'Çapraz kaynak doğrulaması', 'Ters piramit kurgusu'], 'Sahte denge (bothsidesism), kanıtlanmış bilimsel gerçeklerle kanıtsız iddialara "tarafsızlık" görüntüsü altında eşit ağırlık vererek kamuoyunda yapay bir belirsizlik algısı yaratmaktır.'),
  ('Okuyucunun ilgisini çekmek ve tıklama sayısını artırmak amacıyla içeriği tam yansıtmayan abartılı, merak sömürüsüne dayalı çevrimiçi haber başlıklarına ne ad verilir?', 'Tık tuzağı', ['Manşet haberciliği', 'Spot paragrafı', 'Editöryal çerçeve'], 'Tık tuzağı (clickbait), "Bakın ünlü isim ne yaptı, üçüncüsüne inanamayacaksınız!" tarzı bilgi boşluğu yaratan başlıklarla reklam geliri için kullanıcıyı siteye çekme yöntemidir.'),
  ('Siyasal iletişimde rakiplerin bir yasa tasarısını kendi çıkarlarına göre "vergi adaleti reformu" veya "yeni zam paketi" şeklinde farklı yönlerini öne çıkararak tartışmasına ne ad verilir?', 'Vurgu çerçevelemesi', ['Eşdeğerlik çerçevelemesi', 'Mekanik gürültü etkisi', 'Doğrusal kodlama süreci'], 'Kahneman\'ın eşdeğerlik çerçevelemesinden farklı olarak iletişim bilimindeki vurgu çerçevelemesi, karmaşık bir konunun tamamen farklı boyutlarını (ekonomi, ahlak, güvenlik) öne çıkarmaktır.'),
  ('Harold Zucker\'in Gündem Belirleme kuramına getirdiği katkıya göre, medyanın kamuoyu gündemini belirleme gücü hangi tür konularda çok daha yüksektir?', 'Halkın doğrudan deneyimleyemediği "göze çarpmayan" (unobtrusive) konularda', ['İnsanların her gün markette bizzat yaşadığı mutfak enflasyonu gibi konularda', 'Mahalledeki su kesintisi veya toplu taşıma gecikmesi gibi somut sorunlarda', 'Bireylerin kendi aile içi ilişkilerini ilgilendiren gündelik meselelerde'], 'Zucker\'e göre dış politika veya uzay araştırmaları gibi bireyin doğrudan yaşam deneyimi olmayan (unobtrusive) konularda halk tamamen medyaya bağımlı olduğu için gündem belirleme etkisi en güçlüdür.'),
  ('Kamuoyu araştırmalarında örneklemin evreni temsil etmemesi yüzünden 1936 ABD Başkanlık seçimlerinde Alf Landon\'ın kazanacağını öngörerek tarihsel bir yanılgiya düşen ünlü dergi hangisidir?', 'Literary Digest', ['The New Yorker', 'Time Magazine', 'Harper\'s Weekly'], 'Literary Digest dergisi 2,4 milyon kişilik devasa anketini telefon rehberleri ve otomobil kayıtlarına dayandırdığı için Büyük Buhran\'daki yoksul Roosevelt seçmenini kaçırmış ve bilimsel örneklemin önemini kanıtlamıştır.'),
  ('İkna edici bir mesajın kaynağı güvenilmez olduğunda başlangıçta reddedilmesi, ancak zamanla kaynağın unutulup mesaj içeriğinin zihinde kalarak tutum değiştirmesine ne ad verilir?', 'Uyuyan etki (Sleeper effect)', ['Öne çıkarma etkisi (Priming)', 'Rezonans etkisi (Yankılanım)', 'Hale etkisi (Halo effect)'], 'Carl Hovland ve ekibinin II. Dünya Savaşı propaganda filmleri üzerine yaptığı deneylerde keşfettiği "uyuyan etki", zaman geçtikçe güvenilmez kaynak ipucunun mesajdan ayrışıp unutulmasıyla iknanın gecikmeli artmasıdır.'),
  ('Antonio Gramsci\'nin siyaset bilimine kazandırdığı ve medya çalışmalarında "egemen sınıfın dünya görüşünün zor kullanmadan, medya aracılığıyla doğal bir \'ortak duyu\' gibi benimsetilmesi" anlamında kullanılan kavram nedir?', 'Kültürel hegemonya', ['Bilişsel uyumsuzluk', 'İki aşamalı akış', 'Mekanik dayanışma'], 'Gramsci\'nin hegemonya kavramı, iktidarın sadece polis/ordu gücüyle değil; medya, eğitim ve kültür kurumları üzerinden kitlelerin gönüllü rızasını üreterek sürdürülmesini açıklar.'),
  ('Haber üretim sürecinde muhabirlerin emniyet, adliye veya parlamento gibi resmî kurumlara sabitlenerek düzenli haber akışı sağlaması gazetecilik sosyolojisinde hangi kavramla ifade edilir?', 'Haber ağı', ['Yurttaş haberciliği', 'Eşdeğerlik çerçevelemesi', 'Algoritmik filtreleme'], 'Gaye Tuchman\'ın "Making News" çalışmasında incelediği haber ağı (news net / beat) sistemi, haber kuruluşlarının resmî bürokratik kurumlara muhabir yerleştirerek öngörülebilir haber toplamasını sağlar.'),
  ('Bir araştırmacının bir gazetenin bir yıl boyunca yayımladığı göçmen haberlerindeki olumsuz sıfatların ve suç vurgularının sayısını kodlama cetveliyle istatistiksel olarak ölçmesi hangi araştırma yöntemidir?', 'Nicel içerik analizi', ['Derinlemesine mülakat', 'Katılımlı gözlem', 'Odak grup çalışması'], 'Bernard Berelson\'un "iletişimin açık içeriğinin nesnel, sistematik ve nicel betimlemesi" olarak tanımladığı içerik analizi, medya metinlerindeki örüntüleri sayısallaştırarak ortaya koyar.'),
  ('2011 yılında yayımladığı "Filtre Balonu: İnternet Sizden Neyi Saklıyor?" adlı kitabıyla algoritmik kişiselleştirmenin demokrasiye etkisini tartışmaya açan yazar kimdir?', 'Eli Pariser', ['Henry Jenkins', 'Shoshana Zuboff', 'Manuel Castells'], 'Eli Pariser, iki farklı kullanıcının Google\'da aynı kelimeyi arattığında bambaşka sonuçlar gördüğünü fark ederek algoritmik yalıtılmışlığı "filtre balonu" kavramıyla açıklamıştır.'),
  ('"Yöndeşme Kültürü: Eski ve Yeni Medyanın Çarpıştığı Yer" adlı eseriyle yöndeşmeyi salt teknolojik bir birleşme değil, katılımcı bir kültürel dönüşüm olarak tanımlayan kuramcı kimdir?', 'Henry Jenkins', ['George Gerbner', 'Walter Lippmann', 'David Manning White'], 'Henry Jenkins\'e göre yöndeşme, telefonların her şeyi yapmasından ibaret teknolojik bir süreç değil; medya içeriklerinin farklı platformlar arasında akması ve izleyicinin katılımcı hale gelmesidir.'),
  ('Bir film evreninin ana öyküsünün sinemada, yan karakter geçmişinin çizgi romanda, etkileşimli görevlerinin ise video oyununda birbirini tamamlayacak şekilde anlatılmasına ne ad verilir?', 'Transmedya öykücülüğü', ['Ters piramit tekniği', 'Epizodik çerçeveleme', 'Doğrusal yayıncılık'], 'Henry Jenkins\'in tanımladığı transmedya öykücülüğü, aynı içeriğin birebir kopyalanması değil, her bir medya kanalının öykü evrenine kendine özgü ve yeni bir parça eklemesidir.'),
  ('Claire Wardle ve Hossein Derakhshan\'ın "Bilgi Düzensizliği" sınıflandırmasına göre, gerçek/doğru bir bilginin bir kişiye, kuruma veya ülkeye zarar vermek kastıyla sızdırılıp yayılmasına ne ad verilir?', 'Malenformasyon', ['Mezenformasyon', 'Dezenformasyon', 'Sürreal enformasyon'], 'Malenformasyon (malinformation), içeriği gerçek olan özel hayat verilerinin, kişisel yazışmaların veya bağlamından koparılmış gerçek kayıtların sırf zarar verme amacıyla silah olarak kullanılmasıdır.'),
  ('Bir siyasetçinin özel e-posta yazışmalarının seçim arifesinde siber saldırıyla ele geçirilip hiçbir değişiklik yapılmadan itibar suikastı amacıyla basına sızdırılması hangi bilgi düzensizliği türüdür?', 'Malenformasyon', ['Mezenformasyon', 'Parodi habercilik', 'Tık tuzağı'], 'Sızdırılan belgeler gerçek olduğu (sahte olmadığı) halde mahremiyeti ihlal edip kasıtlı zarar verme amacı taşıdığı için Claire Wardle\'ın tipolojisinde malenformasyon kategorisine girer.'),
  ('Sosyal medyada deprem anında paniğe kapılan bir yurttaşın, eski bir bina yıkım videosunu güncel sanarak "yardım gitsin" düşüncesiyle paylaşması hangi kavrama örnektir?', 'Mezenformasyon', ['Dezenformasyon', 'Malenformasyon', 'Kara propaganda'], 'Paylaşımı yapan kişinin amacı insanları aldatmak değil yardım çağrısı yapmak olduğundan zarar kastı yoktur; yanlış bilginin iyi niyetle yayılması mezenformasyondur.'),
  ('Geçmiş yıllarda başka bir ülkede çekilmiş gerçek bir protesto fotoğrafının üzerine hiçbir montaj yapılmadan "Dün gece başkentte olaylar çıktı" notuyla paylaşılması hangi yanıltma türüdür?', 'Yanlış bağlam (False context)', ['Tamamen uydurma içerik (Fabricated content)', 'Derin sahtecilik (Deepfake)', 'Hiciv ve parodi içeriği'], 'Fotoğrafın kendisi gerçek olduğu ve pikselleriyle oynanmadığı halde zaman ve mekân bilgisi değiştirilerek sunulduğu için bu durum "yanlış bağlam" (bağlamından koparma) örneğidir.'),
  ('Oxford Sözlüğü tarafından 2016\'da yılın kelimesi seçilen ve "nesnel gerçeklerin kamuoyunu belirlemede duygular ve kişisel inançlardan daha az etkili olması durumu"nu tanımlayan kavram nedir?', 'Post-truth (Hakikat ötesi)', ['Siber-ütopya (Cyber-utopia)', 'Enformasyon toplumu', 'Bilişsel kapitalizm'], 'Brexit referandumu ve 2016 ABD seçimleri sürecinde öne çıkan "post-truth" (hakikat ötesi / gerçek ötesi), olgusal kanıtların yerini duygusal çağrıların ve kimliksel inançların almasını ifade eder.'),
  ('Sosyal medyada kaynağı belirsiz çarpıcı bir fotoğraf gören medya okuryazarı bir kullanıcının, fotoğrafın ilk kez ne zaman ve nerede yayımlandığını bulmak için başvuracağı en etkili teknik hangisidir?', 'Tersine görsel arama', ['Ekran parlaklığını en üst düzeye çıkarma', 'Görseli farklı bir dosya adıyla bilgisayara kaydetme', 'Paylaşımın altındaki beğeni sayısını kontrol etme'], 'Google Lens, TinEye veya Yandex Görsel gibi araçlarla yapılan tersine görsel arama, bağlamından koparılmış eski fotoğrafların orijinal tarihini ve kaynağını saniyeler içinde ortaya çıkarır.'),
  ('Bir haber kaynağının güvenirliğini değerlendirirken kullanılan "dikey okuma" yönteminin dijital dezenformasyon karşısında yetersiz kalmasının temel nedeni nedir?', 'Sahte haber sitelerinin profesyonel tasarım ve sahte akademik referanslarla güvenilir görünmeyi başarması', ['İnternet tarayıcılarının dikey kaydırma çubuğunu yeni nesil sitelerde tamamen kaldırması', 'Uzun metinlerin mobil telefon ekranlarında teknik olarak hiç görüntülenememesi', 'Dikey okuma yapan kullanıcıların yalnızca görsellere bakıp başlıkları hiç okumaması'], 'Geleneksel dikey okumada okur sayfanın içinde kalarak logonun ciddiyetine veya "Hakkımızda" yazısına aldanabilir; oysa profesyonel dezenformasyon siteleri kurumsal görünümü kolayca taklit eder.'),
  ('Sosyal medyada bir yanlış bilgiyi çürütmek isteyen kullanıcının, yanlış iddiayı tırnak içinde kocaman başlığa taşıyıp doğrusunu en altta küçük harflerle yazması hangi psikolojik riski doğurur?', 'Yanlış iddianın aşinalığını artırarak zihinde daha kalıcı hale gelmesine yol açma', ['Kullanıcıların doğrulama kuruluşlarına olan abonelik ücretlerini artırma', 'Algoritmaların o paylaşımı tamamen silerek hesabı kalıcı olarak kapatması', 'İnternet servis sağlayıcılarının veri indirme hızını yarı yarıya düşürmesi'], 'Doğrulama iletişiminde yanlış iddiayı gereksiz yere tekrarlamak "aşinalık geri tepmesi" ve yanılsamalı gerçeklik etkisi yaratarak okurun bir süre sonra sadece yanlış başlığı hatırlamasına neden olur.'),
  ('Bireylerin henüz gerçek bir dezenformasyon kampanyasıyla karşılaşmadan önce, olası manipülasyon tekniklerinin zayıflatılmış örnekleriyle eğitilerek bağışıklık kazanmasını hedefleyen yaklaşıma ne denir?', 'Ön-çürütme / Aşılama (Prebunking)', ['Sonradan düzeltme (Debunking)', 'Eşik bekçiliği (Gatekeeping)', 'Gündem saptırma (Diversion)'], 'Sosyal psikolog William McGuire\'ın Aşılama Kuramı\'na (Inoculation Theory) dayanan "prebunking" (ön-çürütme), tıpkı biyolojik aşı gibi insanlara manipülasyon taktiklerini önceden tanıtarak zihinsel direnç kazandırır.'),
  ('Shoshana Zuboff\'un teknoloji devlerinin ücretsiz dijital hizmetler karşılığında kullanıcıların davranışsal verilerini toplayıp geleceğe dönük davranış tahmin pazarlarında satmasını tanımladığı kavram nedir?', 'Gözetim Kapitalizmi', ['Kültür Endüstrisi', 'Enformasyon Toplumu', 'Ağ Tarafsızlığı'], 'Harvard profesörü Shoshana Zuboff, 2019 tarihli eserinde insan deneyiminin algoritmik reklam ve davranış yönlendirme için bedava hammaddeye dönüştürülmesini "Gözetim Kapitalizmi" (Surveillance Capitalism) olarak adlandırmıştır.'),
  ('İspanyol sosyolog Manuel Castells\'in dijital iletişim teknolojileriyle birlikte toplumsal yapının hiyerarşik örgütlerden esnek ve küresel düğümlere evrildiğini açıklamak için kullandığı temel kavram nedir?', 'Ağ Toplumu (Network Society)', ['Risk Toplumu (Risk Society)', 'Gösteri Toplumu (Society of the Spectacle)', 'Tüketim Toplumu (Consumer Society)'], 'Manuel Castells, "Enformasyon Çağı" üçlemesinde mikroelektronik ve dijital iletişim ağlarının zaman-mekân algısını dönüştürerek "Ağ Toplumu"nu ortaya çıkardığını kuramsallaştırmıştır.'),
  ('Afet ve kriz anlarında yurttaş gazeteciliğinin geleneksel medyaya kıyasla sağladığı hız avantajının yanında barındırdığı en ciddi medya etiği ve bilgi güvenliği riski nedir?', 'Editöryal doğrulama süzgecinden geçmeyen söylenti ve yanıltıcı görüntülerin hızla yayılması', ['Olay yerinden aktarılan görüntülerin her zaman siyah-beyaz formatta kaydedilmesi', 'Geleneksel televizyon kanallarının uydu frekanslarının teknik olarak kilitlenmesi', 'Basılı gazetelerin kâğıt ithalat maliyetlerinin aynı gün içinde iki katına çıkması'], 'Yurttaş gazeteciliğinde kurumsal eşik bekçiliği ve çift kaynak doğrulaması genellikle bulunmadığı için kriz anlarında teyitsiz iddialar (mezenformasyon) büyük paniğe yol açabilmektedir.'),
  ('Dijital çağda geleneksel editörlerin haber seçme tekelinin kırılıp arama motoru sıralamaları, sosyal medya algoritmaları ve kullanıcı paylaşımlarıyla haber görünürlüğünün şekillenmesine ne ad verilir?', 'Ağlaşmış / Algoritmik eşik bekçiliği', ['Klasik telgraf eşik bekçiliği', 'Otoriter devlet yayıncılığı', 'Tek yönlü hipodermik akış'], 'Geleneksel "Mr. Gates" modelinin yerini alan algoritmik ve ağlaşmış eşik bekçiliğinde (networked gatekeeping), hangi haberin öne çıkacağını yazılım kodları ile kullanıcı etkileşimleri birlikte belirler.'),
  ('MIT araştırmacılarının (Vosoughi, Roy ve Aral) 2006-2017 yılları arasındaki milyonlarca sosyal medya paylaşımını inceleyerek ulaştığı ve Science dergisinde yayımlanan çarpıcı bulgu nedir?', 'Yanlış haberlerin doğru haberlerden çok daha hızlı, daha derine ve daha geniş kitlelere yayıldığı', ['Sosyal botlar silindiğinde yanlış haberlerin yayılma hızının anında sıfıra indiği', 'Doğru ve bilimsel haberlerin yanlış iddialardan ortalama on kat daha hızlı yayıldığı', 'Yalnızca yaşlı kullanıcıların doğru haberleri, gençlerin ise yanlış haberleri paylaştığı'], 'MIT araştırması, yanlış haberlerin yenilik ve şaşkınlık/öfke duygusu uyandırması nedeniyle bizzat gerçek insanlar tarafından doğru haberlerden 6 kat daha hızlı yayıldığını kanıtlamıştır.'),
  ('Bir haber veya reklam metnini incelerken medya okuryazarlığının "Tüm medya mesajları kurgulanmıştır" temel ilkesi aşağıdakilerden hangisini vurgular?', 'Medya içeriklerinin gerçekliğin kendisi değil; belirli seçimler, açılar ve montajlarla üretilmiş temsilleri olduğunu', ['Televizyonda yayımlanan tüm haber bültenlerinin stüdyoda oyuncularla çekilmiş kurmaca diziler olduğunu', 'Gazetecilerin sahada hiçbir gerçek olayı izlemeden bütün haberleri masa başında uydurduğunu', 'Belgesel ve fotoğraf sanatının doğadaki gerçek nesneleri görüntülemesinin teknik olarak imkânsız olduğunu'], 'En nesnel görünen haber fotoğrafında bile kadrajın nereye çevrildiği, neyin dışarıda bırakıldığı ve hangi kelimelerin seçildiği insan eliyle yapılmış bir "inşa/kurgu" (construction) sürecidir.'),
  ('Sosyal medyada bir kişinin kamuya mal olmamış hatası veya tartışmalı bir sözü nedeniyle çevrimiçi kalabalıklar tarafından topluca hedef gösterilip işini ve sosyal çevresini kaybetmeye zorlanmasına ne denir?', 'İptal kültürü / Dijital linç', ['Yurttaş haberciliği dayanışması', 'Demokratik müzakere süreci', 'Kurumsal sosyal sorumluluk'], 'İptal kültürü ve çevrimiçi linç, adil yargılanma veya orantılı eleştiri sınırlarını aşarak kişiyi kamusal ve mesleki yaşamdan tamamen silmeye yönelen kitlesel dijital dışlama pratiğidir.'),
  ('Bir kişinin özel adres, telefon numarası, kimlik bilgisi veya iş yeri gibi mahrem kişisel verilerinin intikam ya da taciz amacıyla rızası dışında internette ifşa edilmesine ne ad verilir?', 'Doxing (Kişisel veri ifşası)', ['Phishing (Oltalama saldırısı)', 'Framing (Haber çerçevelemesi)', 'Priming (Bilişsel hazırlama)'], '"Documents" (belgeler) kelimesinin kısaltmasından türeyen "doxing" (veya doxxing), bireyi fiziksel ve dijital tacize açık hale getirmek için özel bilgilerini kamuya yayma eylemidir.'),
  ('Sosyal medyada sırf tartışmayı sabote etmek, insanları kışkırtıp öfkelendirmek ve konuyu asıl bağlamından koparmak amacıyla kasıtlı olarak provokatif mesajlar yazan kullanıcılara ne ad verilir?', 'İnternet trolü', ['Medya ombudsmanı', 'Serbest muhabir', 'Veri analisti'], 'Trolleme (trolling), yapıcı bir fikir savunmaktan ziyade duygusal kaos yaratmak, muhatabı yıldırmak veya kamusal tartışmayı zehirlemek amacıyla yürütülen kışkırtıcı iletişim davranışıdır.'),
  ('Sosyolog Zeynep Tüfekçi\'nin "Twitter ve Biber Gazı" adlı eserinde incelediği üzere, dijital ağlarla çok hızlı büyüyen modern protesto hareketlerinin yaşadığı en temel yapısal kırılganlık nedir?', 'Örgütsel kurumsallaşma ve uzun hazırlık evresini atladıkları için karar alma ve müzakere kapasitesinde zorlanmaları', ['İnternet üzerinden hiçbir zaman yüz kişiden fazla insanı aynı meydanda toplayamamaları', 'Sosyal medya kullanan gençlerin geleneksel sokak gösterilerine katılmayı tamamen reddetmeleri', 'Fotoğraf ve videoların sosyal medyada paylaşılmasının hareketin görünürlüğünü sıfıra indirmesi'], 'Zeynep Tüfekçi\'ye göre dijital araçlar lojistik engelleri aşarak hareketleri hızla büyütür ("taktiksel donma" yaşatır); ancak geçmişteki uzun örgütlenme sürecinin kazandırdığı ortak karar alma kasları zayıf kalır.'),
  ('Bir medya holdinginin aynı anda hem kâğıt fabrikasına, hem haber ajansına, hem gazete matbaasına hem de dağıtım şirketine sahip olması medya ekonomisinde hangi kavramla adlandırılır?', 'Dikey bütünleşme (Vertical integration)', ['Yatay bütünleşme (Horizontal integration)', 'Çapraz medya sahipliği', 'Kamu yayıncılığı tekeli'], 'Üretimden dağıtıma kadar aynı tedarik zincirinin farklı aşamalarının tek bir şirket bünyesinde toplanmasına dikey bütünleşme denir.'),
  ('Bir medya grubunun hem ulusal bir televizyon kanalını, hem çok satan iki günlük gazeteyi, hem bir radyo istasyonunu hem de popüler bir haber portalını satın alması hangi mülkiyet yapısını oluşturur?', 'Çapraz medya sahipliği', ['Kooperatif medya modeli', 'Bağımsız alternatif yayıncılık', 'Yurttaş medyası ağı'], 'Farklı medya sektörlerindeki (yazılı basın, TV, radyo, internet) kuruluşların aynı sermaye grubunun elinde toplanmasına çapraz medya sahipliği (çapraz tekelleşme) denir ve çoğulculuğu tehdit eder.'),
  ('Toplumun bir kesiminin bilgisayara, hızlı internete ve dijital okuryazarlık becerilerine kolayca erişirken dar gelirli, kırsal veya yaşlı kesimlerin bu olanaklardan yoksun kalmasına ne ad verilir?', 'Dijital uçurum', ['Filtre balonu etkisi', 'Medya yöndeşmesi', 'Yankı odası sendromu'], 'Dijital uçurum (digital divide), birinci düzeyde fiziksel cihaz ve internet erişimi eşitsizliğini, ikinci düzeyde ise bu teknolojileri verimli ve eleştirel kullanma becerisi farkını ifade eder.'),
  ('Büyük veri kümelerini analiz edip istatistiksel bulguları interaktif haritalar, grafikler ve görselleştirmeler eşliğinde kamuoyunun anlayabileceği haber öykülerine dönüştüren gazetecilik dalı hangisidir?', 'Veri gazeteciliği', ['Magazin gazeteciliği', 'Sarı gazetecilik', 'İliştirilmiş gazetecilik'], 'Veri gazeteciliği, açık devlet verilerini, sızdırılan dev belge arşivlerini veya ekonomik istatistikleri kodlama ve görselleştirme araçlarıyla işleyerek kanıta dayalı haber üretir.'),
  ('Son dakika hız rekabetinin yol açtığı yüzeysel ve doğrulanmamış haber kirliliğine tepki olarak doğan; derinlemesine araştırmayı, bağlamı ve doğruluğu hıza tercih eden yaklaşıma ne ad verilir?', 'Yavaş gazetecilik', ['Yurttaş gazeteciliği', 'Algoritmik habercilik', 'Tık tuzağı haberciliği'], '"Yavaş yemek" (Slow Food) hareketinden esinlenen yavaş gazetecilik, "ilk duyuran olma" telaşı yerine "doğru ve derinlikli anlatan olma" ilkesini savunur.'),
  ('Toplumsal sorunları yalnızca kriz, çatışma ve çaresizlik yönüyle bildirmekle kalmayıp bu sorunlara karşı geliştirilmiş başarılı ve kanıta dayalı yanıtları da titizlikle inceleyen habercilik türü nedir?', 'Çözüm gazeteciliği', ['Halkla ilişkiler bülteni', 'Epizodik ajans haberciliği', 'Propaganda yayıncılığı'], 'Çözüm gazeteciliği "iyimser/pembe haber" yapmak değil; bir sorunun başka bir şehir veya ülkede hangi somut yöntemle çözüldüğünü eleştirel ve kanıtlı biçimde raporlayarak kamusal öğrenmeyi sağlamaktır.'),
  ('Özellikle 2003 Irak Savaşı\'nda yaygınlaşan ve muhabirlerin doğrudan askerî birliklerin içine yerleştirilerek güvenlik ve ulaşım karşılığında ordunun belirlediği kurallar çerçevesinde haber izlemesine ne denir?', 'İliştirilmiş gazetecilik', ['Bağımsız savaş muhabirliği', 'Sınır tanımayan gazetecilik', 'Açık kaynak istihbaratı'], 'İliştirilmiş (embedded) gazetecilik muhabire cepheye yakınlık sağlasa da, gazetecinin olayı yalnızca korunduğu askerî birliğin penceresinden görmesine ve nesnelliğin zedelenmesine yol açtığı için eleştirilmiştir.'),
  ('Sosyal medyada "Şok! Ünlü bilim insanı mucize ilacı açıkladı ama dev şirketler videoyu silmeden hemen izleyin!" şeklinde paylaşılan bir gönderi, medya okuryazarlığı açısından hangi kırmızı bayrağı taşır?', 'Aciliyet hissi ve komplo diliyle eleştirel düşünmeyi devre dışı bırakma', ['Akademik makalelerdeki standart kaynakça gösterim kurallarına uyma', 'Çift kör plasebo kontrollü klinik deney sonuçlarını ayrıntılı paylaşma', 'Sağlık Bakanlığı ve üniversite etik kurullarının resmî onay numarasını verme'], 'Dezenformasyon içerikleri "silinmeden paylaşın", "sizden gizlenen gerçek" gibi aciliyet ve komplo kalıpları kullanarak kullanıcının analitik düşünme (Sistem 2) sürecini atlayıp dürtüsel davranmasını hedefler.'),
  ('Deneysel araştırmalara göre sosyal medya kullanıcılarına bir haberi paylaşmadan hemen önce "Bu başlığın doğruluğunu nasıl değerlendirirsiniz?" şeklinde küçük bir hatırlatma (dürtme) yapılmasının temel etkisi nedir?', 'Dikkat odağını popülerlikten doğruluğa çevirerek yanlış bilgi paylaşımını anlamlı ölçüde azaltması', ['Kullanıcıların doğru ve güvenilir haberleri paylaşma oranını tamamen sıfıra indirmesi', 'İnsanların sosyal medya hesaplarını aynı gün içinde kalıcı olarak kapatmasına neden olması', 'Kutuplaştırıcı öfke içeriklerinin beğeni sayısını normalin üç katına çıkarması'], '"Doğruluk dürtmesi" (accuracy nudge / prompt) çalışmaları, insanların aslında yanlış bilgi yaymak istemediğini, ancak sosyal medya ortamı dikkati beğeni/etkileşime çektiği için doğruluğu unuttuklarını göstermiştir.'),
  ('Gazetecilik etiği açısından "advertorial" veya "sponsorlu içerik" yayımlanırken okurun yanıltılmaması için uyulması gereken en temel kural aşağıdakilerden hangisidir?', 'İçeriğin ticari bir reklam olduğunun okurun ilk bakışta açıkça anlayacağı biçimde belirtilmesi', ['Reklam metninin gazetenin en kıdemli siyaset muhabirinin imzasıyla yayımlanması', 'Sponsor şirketin rakiplerini kötüleyen doğrulanmamış iddialara metinde yer verilmesi', 'Ücretli tanıtım yazısının ana haber bülteninde son dakika gelişmesi olarak sunulması'], 'Editöryal bağımsızlık ile ticari reklam arasındaki duvarın (kilise-devlet ayrımı metaforu) korunması ve okurun bir içeriğin haber mi yoksa paralı tanıtım mı olduğunu net olarak bilmesi temel etik ilkedir.'),
  ('Yapay zekâ dil modellerinin (sohbet botlarının) gerçekte var olmayan akademik makaleleri, mahkeme kararlarını veya tarihsel olayları son derece kendinden emin ve akıcı bir dille uydurmasına ne ad verilir?', 'Yapay zekâ halüsinasyonu', ['Derin ağ yöndeşmesi', 'Algoritmik şeffaflık', 'Sentetik çerçeveleme'], 'Büyük dil modelleri olgusal doğruluk veritabanı değil olasılıksal kelime tahmin motorları olduğu için, bilmedikleri konularda tutarlı görünen ama tamamen uydurma bilgiler üretebilir; buna "halüsinasyon" denir.'),
  ('Felaket ve kriz dönemlerinde bireyin kendini üzüntü, kaygı ve çaresizlik içinde hissetmesine rağmen elinden telefonu bırakamayıp saatlerce art arda kötü ve karamsar haberleri kaydırarak okumasına ne denir?', 'Felaket kaydırması (Doomscrolling)', ['Yatay doğrulama (Lateral reading)', 'Yavaş gazetecilik (Slow journalism)', 'Seçici kaçınma (Selective avoidance)'], 'Özellikle küresel salgın ve afet dönemlerinde literatüre yerleşen "doomscrolling" (felaket kaydırması), belirsizlik karşısında kontrol hissi arayan beynin olumsuz haber döngüsüne hapsolmasıdır.'),
  ('Suskunluk Sarmalı kuramının dijital sosyal medya ortamında yeniden test edildiği araştırmalar (örneğin Pew Research çalışmaları), insanların tartışmalı konularda sosyal medyada nasıl davrandığını göstermiştir?', 'Sosyal medyadaki dışlanma korkusunun bireyleri hem çevrimiçi hem yüz yüze ortamda görüş bildirmekten caydırabildiğini', ['Anonimlik sayesinde istisnasız her kullanıcının azınlık görüşlerini hiçbir çekince duymadan paylaştığını', 'Sosyal medya kullanan bireylerin arkadaş çevrelerindeki siyasi görüşlerden hiç haberdar olmadığını', 'Dijital platformlarda çoğunluk ve azınlık algısının tamamen ortadan kalkarak tam eşitlik sağlandığını'], 'Başlangıçta internetin Suskunluk Sarmalı\'nı bitireceği düşünülse de araştırmalar, "bağlam çökmesi" ve dijital linç korkusu nedeniyle kullanıcıların kendi ağları kendileriyle hemfikir değilse sosyal medyada da sustuğunu göstermiştir.'),
  ('Wilbur Schramm\'ın dairesel iletişim modelini Shannon-Weaver modelinden ayıran en temel kavramsal yenilik aşağıdakilerden hangisidir?', 'Kaynak ile alıcının rollerinin sürekli yer değiştirmesi ve ortak yaşantı alanının vurgulanması', ['İletinin yalnızca tek yönlü bir sinyal aktarımı olarak matematiksel kesinlikle ölçülmesi', 'Kitle iletişim araçlarının bireyler üzerinde doğrudan ve sınırsız etkiye sahip olduğunun savunulması', 'Sözsüz iletişim unsurlarının iletişimin doğruluğunu bozan birer teknik gürültü sayılması'], 'Schramm modelinde iletişim karşılıklıdır; kaynak ve alıcı sürekli kodlayıcı, yorumlayıcı ve kod çözücü rollerini üstlenir, ayrıca ortak yaşantı alanı şarttır.'),
  ('Bir tıp doktorunun hastasına hastalığını ağır Latince terimlerle anlatması sonucunda hastanın söyleneni anlayamaması, iletişim kuramlarında hangi engelle açıklanır?', 'Anlamsal (semantik) gürültü', ['Fiziksel kanal paraziti', 'Mekanik iletim kopukluğu', 'Fizyolojik işitme kaybı'], 'Fiziksel ses iletiminde sorun olmamasına rağmen kullanılan sembol ve kelimelerin alıcıda karşılık bulmaması semantik gürültüdür.'),
  ('Bir iş görüşmesinde adayın mülakat komisyonu üyeleriyle ne el uzatacak kadar yakın ne de bağırarak konuşacak kadar uzak bir noktada (yaklaşık 1,2 ile 3,6 metre arasında) oturması hangi proksemik bölgeye örnektir?', 'Sosyal mesafe', ['Mahrem mesafe', 'Kamusal mesafe', 'Biyolojik mesafe'], 'Resmi iş ilişkileri, mülakatlar ve tanışıklığın sınırlı olduğu profesyonel etkileşimler 1,2-3,6 metre aralığındaki sosyal mesafede gerçekleşir.'),
  ('Sözsüz iletişim araştırmalarında yüz ifadeleri, jestler, duruş (postür) ve beden hareketlerinin iletişimsel işlevlerini inceleyen bilim dalı hangisidir?', 'Kinesik', ['Proksemik', 'Paralinguistik', 'Semantik'], 'Ray Birdwhistell\'in öncülük ettiği kinesik, beden hareketlerinin ve jestlerin iletişimsel anlamlarını inceler.'),
  ('Etkin dinleme sürecinde, dinleyicinin konuşmacının söylediği sözleri kendi kelimeleriyle özetleyerek ona geri sunmasına (örneğin "Yani bu karardan dolayı haksızlığa uğradığını düşünüyorsun") ne ad verilir?', 'Yansıtma', ['Semantik gürültü oluşturma', 'Tek yönlü kodlama yapma', 'Proksemik sınır koyma'], 'Etkin dinlemede içerik ve duygu yansıtması, konuşmacıya anlaşıldığını hissettiren ve anlamı doğrulayan temel tekniktir.'),
  ('İletişim engelleri bağlamında Thomas Gordon\'un "İletişimin On İki Engeli" listesinde yer alan "Teselli etme / konuyu değiştirme" tepkisinin etkin dinlemeyi bozma nedeni nedir?', 'Konuşmacının yaşadığı duygunun önemini küçümsemesi ve kişinin kendi sorununu irdelemesini önlemesi', ['Alıcının işitsel kanalında fiziksel bir ses yankılanması meydana getirmesi', 'Kaynağın gönderdiği mesajdaki tüm dilbilgisi kurallarını geçersiz kılması', 'İletişim ortamındaki kamusal mesafeyi aniden mahrem mesafeye dönüştürmesi'], 'Sorunu geçiştiren teselli cümleleri bireyin duygusunun anlaşılmadığı mesajını verir ve iletişimi yüzeysel bırakır.'),
  ('Lasswell\'in iletişim modeline yöneltilen en önemli akademik eleştirilerden biri aşağıdakilerden hangisidir?', 'Geri bildirim (feedback) öğesini içermediği için iletişimi tek yönlü bir ikna süreci olarak ele alması', ['Kitle iletişim araçlarını tamamen göz ardı ederek yalnızca yüz yüze sohbetleri incelemesi', 'İletişim sürecindeki kaynak ve alıcı kavramlarını birbirinden ayırmayı reddetmesi', 'Mesajın içeriğini incelemek yerine yalnızca telefon kablolarının direncini hesaplaması'], 'Lasswell modeli propaganda araştırmalarından doğduğu için geri bildirimi barındırmaz ve doğrusal-etki odaklıdır.'),
  ('Üniversite amfisinde yüzlerce öğrenciye hitap eden bir profesörün kürsü ile ön sıralar arasında bıraktığı 4 metrelik açıklık, Hall\'un proksemik kuramında hangi kategoriye girer?', 'Kamusal mesafe', ['Sosyal mesafe', 'Kişisel mesafe', 'Mahrem mesafe'], 'Yaklaşık 3,6 metreden (12 fit) başlayıp daha uzağa uzanan ve topluluğa hitaplarda kullanılan alan kamusal mesafedir.'),
  ('Bir yöneticinin odasına gelen çalışanını ayakta bekletirken kendisinin telefonla ilgilenmeye devam etmesi, sözsüz iletişimin hangi iki alanının güç gösterisi amacıyla bir arada kullanılmasına örnektir?', 'Kronemik ve proksemik', ['Semantik ve sentaktik', 'Fonetik ve morfolojik', 'Mekanik ve elektronik'], 'Çalışanın zamanını bekletmek kronemik, makam masası ve ayakta tutma yoluyla mekanı hiyerarşik kullanmak proksemik güç mesajıdır.'),
  ('Paul Ekman ve Wallace Friesen\'in sözsüz davranış sınıflandırmasında, konuşma olmadan da tek başına sözlük anlamı taşıyan ve kültürden kültüre değişebilen el hareketlerine (örneğin "tamam" işareti) ne ad verilir?', 'Amblemler', ['Adaptörler', 'Duygu gösterimleri', 'Düzenleyiciler'], 'Amblemler, doğrudan belirli bir sözcük ya da cümlenin yerine geçen ve o kültürde uzlaşımsal anlamı olan jestlerdir.'),
  ('Etkili bir "ben dili" cümlesinin eksiksiz kurgulanabilmesi için aşağıdaki bileşen üçlüsünden hangisinin bir arada bulunması gerekir?', 'Karşı tarafın somut davranışı + davranışın bizdeki somut etkisi + bizde uyandırdığı duygu', ['Karşı tarafın karakter analizi + geçmişteki hatalarının listesi + gelecekteki ceza uyarısı', 'Toplumsal ahlak kuralları + otoritenin beklentisi + konuşmacının üstünlük vurgusu', 'Soyut bir sitem ifadesi + dolaylı ima + sessiz kalarak küsmek'], 'Gordon\'un modelinde ben dili; yargısız davranış tanımı, somut/maddi sonuç ve yaşanan birincil duygudan oluşur.'),
  ('Çocuğu salonda top oynarken vazoyu düşürme tehlikesi yarattığında bir ebeveynin "ben dili" kurallarına tam uygun olarak kuracağı cümle aşağıdakilerden hangisidir?', 'Salonda top oynadığında vazonun kırılmasından ve bir yerinin incinmesinden korkuyorum.', ['Ne kadar yaramaz ve laftan anlamaz bir çocuk olduğunu yine kanıtladın!', 'Salonda top oynamanın kesinlikle yasak olduğunu daha kaç defa söylemem gerekiyor?', 'Beni üzmekten ve evdeki eşyalara zarar vermekten özel bir zevk alıyorsun.'], 'İlk seçenek suçlama içermez; davranışı (salonda top oynamak), somut riski ve ebeveynin gerçek duygusunu (korku/endişe) belirtir.'),
  ('Konuşmacının anlattıklarının tamamını anlamak yerine yalnızca kendi fikrini doğrulayacak ya da karşı tarafa saldıracak açıkları yakalamaya odaklanan dinleme biçimi hangisidir?', 'Savunmacı / tuzak kurucu dinleme', ['Kapsamlı ve katılımcı dinleme', 'Empatik ve yansıtıcı dinleme', 'Bütüncül içerik dinlemesi'], 'Tuzak kurucu veya savunmacı dinlemede amaç anlamak değil, konuşmacının zayıf noktasını yakalayıp karşı argüman geliştirmektir.'),
  ('David Berlo tarafından 1960 yılında geliştirilen ve "SMCR" kısaltmasıyla bilinen iletişim modelinin dört temel unsuru sırasıyla hangileridir?', 'Kaynak - Mesaj - Kanal - Alıcı', ['Sinyal - Mekan - Çevre - Refleks', 'Sembol - Medya - Cevap - Rapor', 'Sistem - Merkez - Cihaz - Rezonans'], 'Berlo\'nun SMCR modeli Source (Kaynak), Message (Mesaj), Channel (Kanal) ve Receiver (Alıcı) bileşenlerinden oluşur.'),
  ('Frank Dance tarafından önerilen "Sarmal (Helix) İletişim Modeli", dairesel modellere hangi temel eleştiriyi getirerek süreci sarmal bir yay biçiminde betimlemiştir?', 'Dairesel modellerin iletişimi başladığı noktaya aynen geri dönüyormuş gibi göstermesi, oysa her iletişimin önceki deneyimlerle genişleyerek ilerlemesi', ['İletişimin yalnızca yukarıdan aşağıya doğru askeri emir-komuta zinciriyle gerçekleşmesi', 'Sözlü iletişimin tarihsel süreçte tamamen yok olup yerini yalnızca yazılı metinlere bırakması', 'Kitle iletişim araçlarının bireyler arasındaki tüm yüz yüze etkileşimleri sıfırlaması'], 'Dance\'e göre iletişim tam bir daire çizip başlangıç noktasına dönmez; her etkileşim bir sonrakini etkileyerek sarmal biçimde büyür.'),
  ('Akdeniz ve Orta Doğu kültürlerinde sohbet eden iki arkadaşın Kuzey Avrupa kültürlerindeki bireylere kıyasla birbirine çok daha yakın durması Edward T. Hall\'un hangi kavram çiftiyle açıklanır?', 'Temas kültürleri ve temas dışı (uzak mesafeli) kültürler', ['Sözlü kültürler ve elektronik ikincil kültürler', 'Sanayi öncesi kültürler ve post-endüstriyel kültürler', 'Yüksek okuryazar kültürler ve hiyerarşik bürokratik kültürler'], 'Hall, fiziksel yakınlık ve dokunmanın yoğun olduğu toplumları "temas kültürleri" (contact cultures), mesafeli toplumları ise "temas dışı kültürler" olarak ayırır.'),
  ('George Gerbner\'in 1956 tarihli genel iletişim modelini Shannon-Weaver modelinden ayıran en belirgin özellik aşağıdakilerden hangisidir?', 'İletişim sürecini bir olayın algılanması ve bu algının seçici biçimde temsil edilmesi süreciyle başlatması', ['İletişimi yalnızca radyo dalgalarının atmosferdeki kırılma açıları üzerinden formüle etmesi', 'Alıcının mesajı yorumlama kapasitesini tamamen reddederek mekanik tepkiyi esas alması', 'Kitle iletişim araçları ile kişiler arası iletişim arasında hiçbir yapısal bağlantı kurmaması'], 'Gerbner modeli, gerçeklikteki bir olayın (E) algılayan özne (M) tarafından bağlama göre seçilerek algılanması (E1) boyutuyla başlar.'),
  ('Westley ve MacLean\'in 1957\'de geliştirdiği kitle iletişim modelinde, olayları seçip süzerek hedef kitleye aktaran gazeteci ve editörleri temsil eden "C" rolü literatürde hangi kavramla anılır?', 'Eşik bekçisi (gatekeeper)', ['Kanaat önderi (opinion leader)', 'Pasif kod çözücü', 'Semantik gürültü kaynağı'], 'Westley-MacLean modelinde "C" (kanal/medya kuruluşu), çevredeki sayısız olaydan hangilerinin haberleştirileceğini seçen eşik bekçisi işlevi görür.'),
  ('İnsanların kütüphane masasına çantasını veya ceketini bırakarak o koltuğun kendisine ait olduğu mesajını çevredekilere iletmesi proksemikte hangi kavramla ifade edilir?', 'Alansallık (teritoryallik) işaretleyicileri', ['Paralinguistik ses tonlaması', 'Semantik kodlama hatası', 'Dairesel geri bildirim döngüsü'], 'Bireylerin geçici ya da kalıcı olarak bir mekanı sahiplenmek için eşyalarını sınır koyucu biçimde kullanması alansallık işaretleyicisidir.'),
  ('Sınavdan düşük not aldığı için ağlayan bir öğrenciye rehber öğretmenin "Sınav sonucun beklentinin altında kaldığı için şu an büyük bir hayal kırıklığı yaşıyorsun" demesi hangi beceriye örnektir?', 'Duygu yansıtması', ['Ahlak dersi verme', 'Mantıksal sorgulama', 'Konuyu saptırma'], 'Öğrencinin yaşadığı duygusal durumu isimlendirip yargısızca geri sunmak etkin dinlemedeki duygu yansıtması basamağıdır.'),
  ('İletişim sürecinde bir kişinin giyim tarzı, taktığı aksesuarlar, kullandığı gözlük veya rozetler aracılığıyla kimliği ve statüsü hakkında mesaj vermesi sözsüz iletişimin hangi boyutuyla ilgilidir?', 'Artefaktlar (nesnel kodlar)', ['Vokalik (ses nitelikleri)', 'Okülesik (göz teması)', 'Kronemik (zaman algısı)'], 'Bireyin üzerinde taşıdığı veya çevresinde düzenlediği maddi nesneler aracılığıyla kurduğu sözsüz iletişime artefakt iletişimi denir.'),
  ('Açlığı veya uykusuzluğu nedeniyle derse odaklanamayan bir öğrencinin öğretmenin anlattıklarını kaçırması, iletişim sürecindeki gürültü türlerinden hangisine örnektir?', 'Fizyolojik (nörofizyolojik) gürültü', ['Mekanik kanal gürültüsü', 'Mimari çevresel gürültü', 'Kültürel kod uyuşmazlığı'], 'Alıcı veya kaynağın açlık, ağrı, yorgunluk, işitme engeli gibi bedensel durumlarından kaynaklanan engeller fizyolojik gürültüdür.'),
  ('Kalabalık bir asansöre binen insanların birbirlerine fiziksel olarak çok yaklaşmak zorunda kaldıklarında göz temasından kaçınıp tavan veya kat numaralarına bakması hangi işlevi görür?', 'Zorunlu mahrem mesafe ihlalini telafi ederek psikolojik mahremiyeti korumak', ['Asansörün mekanik hızını artırarak zaman tasarrufu sağlamak', 'Diğer yolculara sözlü bir tartışma başlatmak istediklerini bildirmek', 'Sosyal statü farklarını vurgulayarak liderlik iddiasında bulunmak'], 'Fiziksel mahrem mesafe istemeden ihlal edildiğinde (denge kuramı/equilibrium theory gereği) bireyler göz temasını keserek mahremiyeti dengeler.'),
  ('Bir takım arkadaşının proje raporunu geç teslim etmesi üzerine ekip liderinin "Rapor bana zamanında ulaşmadığında sunum hazırlığım aksıyor ve müşteriye karşı mahcup olmaktan endişeleniyorum" demesi neden etkilidir?', 'Kişiliğe saldırmadan sorunun iş sürecindeki somut sonucunu ve yarattığı duyguyu netleştirdiği için', ['Çalışanın özgüvenini kırarak bir daha ekipte söz almasını engellediği için', 'Sorunun sorumluluğunu tamamen müşterinin üzerine yıkarak gerilimi gizlediği için', 'Mesajı belirsiz imalarla süsleyerek çalışanın hatasını kendisinin tahmin etmesini beklediği için'], 'Bu ifade ben dilinin tüm ilkelerini taşır; savunma yaratmadan davranış değişikliği motivasyonu sağlar.'),
  ('Gürültülü bir fabrika ortamında ustabaşının işçiye bağırmak yerine eliyle "makineyi durdur" işareti yapması, sözsüz iletişimin hangi işlevine örnektir?', 'Sözlü mesajın yerine geçme', ['Sözlü mesajla çelişme', 'Semantik gürültü üretme', 'Kronemik zamanlama yapma'], 'Sözel iletişimin imkansız veya gereksiz olduğu durumlarda beden hareketinin kelimelerin yerini alması ikame (substitution) işlevidir.'),
  ('Bir kişinin "Hiç kızmadım, gayet sakinim!" derken yumruklarını sıkması, yüzünün kızarması ve sesinin yükselmesi durumunda alıcılar genellikle hangi kanala güvenir ve bu durum ne olarak adlandırılır?', 'Sözsüz kanala güvenirler; bu durum sözlü ve sözsüz mesajlar arasındaki çelişme (tutarsızlık) olarak adlandırılır', ['Sözlü kanala güvenirler; çünkü kelimeler insan iradesinden tamamen bağımsız üretilir', 'İki kanalı da reddederler; çünkü aynı anda hem konuşup hem hareket etmek fiziksel olarak imkansızdır', 'Yalnızca yazılı bir belge talep ederler; çünkü yüz yüze iletişimde geri bildirim bulunmaz'], 'Sözsüz tepkilerin denetlenmesi kelimelerden daha zor olduğu için çelişki (çifte mesaj) anında alıcılar beden dilini daha gerçekçi bulur.'),
  ('Wilbur Schramm\'a göre iki bireyin sağlıklı iletişim kurabilmesi için "ortak yaşantı alanı"nın (field of experience) kesişmesi ne anlama gelir?', 'Tarafların paylaştığı dil, kültür, bilgi birikimi ve deneyimlerin benzer sembolleri benzer şekilde anlamlandırmaya yetmesi', ['Kaynak ve alıcının mutlaka aynı gün doğmuş ve aynı mahallede büyümüş olması', 'İletişime katılan kişilerin tüm siyasi ve sanatsal konularda tıpatıp aynı görüşü savunması', 'Konuşmacı ile dinleyicinin aralarında en fazla kırk beş santimetre mesafe bırakması'], 'Ortak yaşantı alanı kesişmediğinde (örneğin hiç bilinmeyen bir dil konuşulduğunda) kodlama ve kod açma süreçleri örtüşmez.'),
  ('Bir öğretmenin sınıfta söz almak isteyen öğrenciye konuşmasını kesmeden yalnızca eliyle "bir dakika bekle" işareti yapması, sözsüz davranışların hangi işlevini yerine getirir?', 'Etkileşimi düzenleme', ['Fiziksel gürültü yaratma', 'Kamusal mesafeyi sıfırlama', 'Anlamsal kodları bozma'], 'Konuşma sırasını belirleyen, sözü başlatan veya bekleten jest, bakış ve baş hareketleri düzenleyici (regulator) işlev görür.'),
  ('Arkadaşı "İş yerindeki yeni yazılıma bir türlü alışamadım, kendimi çok yetersiz hissediyorum" dediğinde "Boş ver, kafana takma, akşam maça gidelim unutursun!" diyen biri hangi iletişim engelini kullanmıştır?', 'Avutma / konuyu saptırma', ['Empatik duygu yansıtması', 'Ben diliyle sınır koyma', 'Açık uçlu soruyla derinleştirme'], 'İyi niyetli görünse de "kafana takma, unutursun" demek kişinin yaşadığı yetersizlik duygusunu geçiştirir ve anlaşılmadığı hissi yaratır.'),
  ('Bir konuşmacının dinleyicilerle göz temasını tüm salona eşit dağıtmak yerine sürekli yalnızca tek bir kişiye bakarak konuşması, diğer dinleyiciler üzerinde nasıl bir iletişimsel etki yaratır?', 'Dışlanmışlık hissi oluşturarak geri kalan dinleyicilerin ilgi ve katılımını düşürür', ['Salondaki mekanik ses yankısını tamamen ortadan kaldırarak akustiği iyileştirir', 'Diğer dinleyicilerin konuşulan konuyu çok daha hızlı ezberlemesini sağlar', 'Kamusal mesafeyi tüm salon için mahrem mesafeye dönüştürür'], 'Topluluk önünde okülesik (göz teması) dengesiz kullanıldığında bakılmayan kesim iletişimin muhatabı olmadığı duygusuna kapılır.'),
  ('Paul Ekman\'ın "gösterim kuralları" (display rules) kavramı, evrensel duyguların yüz ifadelerine yansımasında kültürün nasıl bir rol oynadığını açıklar?', 'Duygular evrensel olsa bile hangi duygunun nerede, kime ve ne ölçüde belli edileceğini kültürel normların belirlediğini', ['Her kültürün tamamen farklı yüz kaslarına sahip olduğunu ve üzüntü hissini fizyolojik olarak yaşayamadığını', 'Bireylerin hiçbir kültürde duygularını gizleme veya abartma yeteneğine sahip olmadığını', 'Kitle iletişim araçlarının yüz ifadelerini tamamen ortadan kaldırarak insanları duygusuzlaştırdığını'], 'Gösterim kuralları; bir kültürün öfkeyi veya üzüntüyü topluluk içinde bastırmayı, maskelemeyi ya da yoğunlaştırmayı öğretmesidir.'),
  ('Yüksek sesle çalışan bir inşaat makinesinin yanından geçerken iki arkadaşın birbirinin söylediklerini duyamaması iletişim modellerinde hangi gürültü türüne doğrudan örnektir?', 'Fiziksel (çevresel) gürültü', ['Semantik (anlamsal) gürültü', 'Psikolojik (tutumsal) gürültü', 'Kültürel (bağlamsal) gürültü'], 'Ortamdan kaynaklanan ve ses dalgalarının fiziksel iletimini bastıran dış sesler fiziksel/çevresel gürültüdür.'),
  ('Paul Lazarsfeld ve Elihu Katz\'ın "Kişisel Etki" (Personal Influence) çalışması, erken dönem "hipodermik iğne / sihirli mermi" anlayışını hangi temel bulguyla çürütmüştür?', 'İzleyicilerin atomize ve savunmasız bireyler olmadığını, birincil grup ilişkilerinin medya etkisini sınırlandırıp aracılık ettiğini göstererek', ['Kitle iletişim araçlarının toplum üzerinde hiçbir koşulda en ufak bir bilgilendirme bile yapamadığını savunarak', 'Radyo ve gazetelerin yalnızca okuma yazma bilmeyen kırsal kesim üzerinde mutlak itaat yarattığını kanıtlayarak', 'Seçmenlerin oy verme kararlarını yalnızca parti liderlerinin fiziksel boy uzunluğuna bakarak verdiğini bularak'], 'Sihirli mermi modeli medyanın doğrudan ve sınırsız etkisini varsayarken, Lazarsfeld medyanın etkisinin kişiler arası ağlar nedeniyle sınırlı (pekiştirici) olduğunu kanıtlamıştır.'),
  ('Lazarsfeld\'in 1940 Erie County seçim araştırmasında, siyasal kampanya medyasının seçmen davranışları üzerinde en çok hangi etkiyi yarattığı saptanmıştır?', 'Mevcut siyasal eğilimleri pekiştirme (güçlendirme)', ['Kararlı seçmenlerin tamamını karşı partiye geçirme (dönüştürme)', 'Seçmenlerin oy kullanma oranını sıfıra indirme', 'Tüm seçmenleri parti programlarından tamamen soğutma'], 'Araştırma, kampanyaların seçmenlerin fikrini kökten değiştirmekten (conversion) ziyade mevcut tutumlarını pekiştirdiğini (reinforcement) ve kararsızları harekete geçirdiğini göstermiştir.'),
  ('Yoğun ve stresli geçen bir iş gününün ardından bir çalışanın yalnızca zihnini dağıtmak ve günlük kaygılarından uzaklaşmak amacıyla komedi dizisi izlemesi, kullanımlar ve doyumlar kuramında hangi ihtiyaca karşılık gelir?', 'Gerilimden kurtulma ve kaçış (oyalanma) ihtiyacı', ['Bilişsel enformasyon ve gözetim ihtiyacı', 'Resmi bürokratik statü kazanma ihtiyacı', 'Yasal mevzuatı ezberleme ihtiyacı'], 'Katz, Gurevitch ve Haas\'ın sınıflandırmasında sıkıntıdan uzaklaşma ve duygusal rahatlama "gerilimden kurtulma / kaçış" (tension-release / diversion) doyumudur.'),
  ('Bir gencin arkadaş grubundaki sohbetlerden geri kalmamak ve ortak konuşma konusu edinmek için popüler bir yarışma programını izlemesi, kullanımlar ve doyumlar kuramındaki hangi işlevle açıklanır?', 'Sosyal bütünleşme ve kişiler arası etkileşim', ['Bilişsel akademik uzmanlaşma', 'Fiziksel kanal kapasitesini ölçme', 'Tek yönlü propaganda üretme'], 'Medya içeriklerini sosyal ilişkilerde sohbet malzemesi ve aidiyet aracı olarak kullanmak sosyal bütünleşme (social integrative) doyumudur.'),
  ('Adorno ve Horkheimer\'ın "kitle kültürü" terimi yerine özellikle "kültür endüstrisi" kavramını tercih etmelerinin temel nedeni nedir?', 'Bu kültürün halkın bağrından kendiliğinden doğan bir kültür olmadığını, yukarıdan aşağıya fabrikasyon biçimde üretilip kitlelere dayatıldığını vurgulamak', ['Sanayi devriminden sonra tüm sanatçıların yalnızca demir-çelik fabrikalarında işçi olarak çalıştığını kanıtlamak', 'Halk türkülerinin ve geleneksel el sanatlarının modern sinemadan daha karlı bir ticari sektör olduğunu göstermek', 'Kitle iletişim araçlarının devlet tekeline alınarak tüm özel şirketlerin kapatılmasını savunmak'], 'Düşünürlere göre "kitle kültürü" ifadesi sanki kitlelerin kendi ürettiği otantik bir kültürmüş yanılsaması yaratır; oysa bu kültür endüstriyel olarak imal edilir.'),
  ('Theodor W. Adorno\'nun popüler müzik ve sinema ürünlerini eleştirirken kullandığı "sahte bireyselleşme" (pseudo-individualization) kavramı neyi anlatır?', 'Özünde aynı standart kalıplarla üretilen kültür ürünlerinin küçük yüzeysel farklarla süslenerek tüketiciye özgün ve kişiye özelmiş gibi sunulmasını', ['Sanatçıların eserlerine gerçek isimlerini yazmak yerine her filmde farklı bir takma ad kullanmasını', 'Bireylerin sinema salonlarında tek kişilik localarda oturarak diğer izleyicilerle konuşmamasını', 'Kitle iletişim araçlarının her vatandaş için tamamen benzersiz ve tekrarsız bir senfoni besteletmesini'], 'Standartlaşmış popüler kültür ürünleri (örneğin hit şarkılar), ufak aranje veya ambalaj değişiklikleriyle özgür seçim ve yenilik yanılsaması yaratır.'),
  ('Marshall McLuhan\'ın iletişim araçlarını insanın hangi yönünün dışsallaşmış birer "uzantısı" (extension of man) olarak tanımladığı bilinmektedir?', 'Duyu organlarının ve merkezi sinir sisteminin', ['Yalnızca ekonomik mülkiyet haklarının', 'Biyolojik sindirim ve solunum sisteminin', 'Geleneksel akrabalık ve kabile kurallarının'], 'McLuhan\'a göre tekerlek ayağın, kitap gözün, radyo kulağın, elektronik medya ise merkezi sinir sistemimizin bir uzantısıdır.'),
  ('McLuhan\'ın medya sınıflandırmasında tek bir duyuya yüksek yoğunluklu (yüksek tanımlı / veri dolu) bilgi sunarak alıcının boşluk doldurma katılımını az gerektiren araçlara ne ad verilir?', 'Sıcak araçlar (hot media)', ['Soğuk araçlar (cool media)', 'Doğrusal gürültü araçları', 'Kanaat önderi araçları'], 'Fotoğraf, radyo, sinema ve basılı kitap gibi yüksek tanımlı (high-definition) ve düşük katılımlı araçlar McLuhan\'da "sıcak araçlar" olarak adlandırılır.'),
  ('McLuhan\'ın sıcak ve soğuk araçlar ayrımına göre; çözünürlüğü/verisi daha düşük olduğu için alıcının zihinsel olarak boşlukları tamamlamasını ve yüksek katılım göstermesini gerektiren "soğuk araç" örneği hangisidir?', 'Karikatür ve telefon', ['Sinema filmi ve fotoğraf', 'Matbu ansiklopedi ve radyo', 'Yüksek çözünürlüklü yağlı boya tablo'], 'Karikatür, telefon ve (McLuhan dönemindeki düşük taramalı) televizyon az detay sunduğu için izleyicinin/dinleyicinin yüksek duyusal tamamlama katılımını gerektiren soğuk araçlardır.'),
  ('Harold Innis\'in sınıflandırmasına göre taş yazıtlar ve parşömen gibi ağır, zor taşınan ancak yüzyıllarca bozulmadan kalan iletişim ortamları hangi toplumsal yapıyı destekler?', 'Gelenek, din ve süreklilik odaklı hiyerarşik toplumları (zaman yanlı iletişim)', ['Geniş toprakları askeri ve ticari bürokrasiyle yöneten merkezi imparatorlukları (mekan yanlı iletişim)', 'Anlık borsa spekülasyonlarıyla işleyen küresel tüketim toplumlarını', 'Hiçbir tarihsel belleği bulunmayan göçebe avcı-toplayıcı toplulukları'], 'Zaman yanlı (time-biased) araçlar kalıcıdır; kuşaklar arası geleneği ve dini otoritenin bilgi tekelini korur.'),
  ('Bir seçmenin gazetedeki köşe yazılarını doğrudan okumak yerine, mahallesindeki bilgisine güvendiği emekli öğretmenin o yazılar hakkındaki yorumlarını dinleyerek karar vermesi hangi kuramı doğrular?', 'Lazarsfeld\'in iki aşamalı akış modelini', ['Shannon\'ın matematiksel sinyal modelini', 'Adorno\'nun kültür endüstrisi standartlaşmasını', 'Hall\'un proksemik mahrem mesafe kuralını'], 'Medya mesajının önce kanaat önderine (emekli öğretmen), oradan kişiler arası iletişimle seçmene ulaşması iki aşamalı akışın tipik örneğidir.'),
  ('Paul Lazarsfeld ve Robert K. Merton\'un 1948 tarihli ünlü makalesinde, kitle iletişim araçlarının bireyleri toplumsal sorunlar hakkında bilgilendirirken aslında onları eyleme geçmek yerine sadece haberdar olmayı yeterli görmeye itmesine ne ad verilir?', 'Uyuşturucu işlev bozukluğu', ['Statü kazandırma işlevi', 'Toplumsal normları uygulama işlevi', 'Semantik kod çözme işlevi'], 'Narkotize edici işlev bozukluğu, aşırı haber tüketen bireyin "bilmeyi" "bir şey yapmakla" karıştırarak politik kayıtsızlığa sürüklenmesidir.'),
  ('Kullanımlar ve doyumlar kuramında Denis McQuail ve arkadaşlarının belirlediği dört temel doyum kategorisinden biri olan "kişisel kimlik" (personal identity) ihtiyacı neyi kapsar?', 'Bireyin medya karakterleriyle özdeşleşerek kendi değerlerini pekiştirmesini ve davranış modelleri keşfetmesini', ['Bireyin hava durumu ve trafik yoğunluğu hakkında anlık pratik bilgi edinmesini', 'Bireyin iş stresinden kaçmak için uyuyakalana kadar rastgele kanal değiştirmesini', 'Bireyin komşularıyla konuşacak magazin gündemi biriktirmesini'], 'Kişisel kimlik doyumu; değer pekiştirme, kendini tanıma ve medya temsilleri üzerinden rol modeli arayışıyla ilgilidir.'),
  ('Sabah evden çıkmadan önce döviz kurlarını, hava durumunu ve dünyadaki son gelişmeleri öğrenmek için haber bülteni açan bir izleyici, kullanımlar ve doyumlar kuramına göre hangi doyumu aramaktadır?', 'Gözetim (bilişsel bilgi edinme)', ['Oyalanma (duygusal kaçış)', 'Parasosyal arkadaşlık kurma', 'Geleneksel ritüel tekrarı'], 'Çevrede olup bitenleri izleme, merak giderme ve bilgi edinme ihtiyacı "gözetim" (surveillance) veya bilişsel ihtiyaç kategorisindedir.'),
  ('Herbert Marcuse\'nin "yanlış (sahte) ihtiyaçlar" kavramı kültür endüstrisi bağlamında neyi ifade eder?', 'Reklam ve medya aracılığıyla bireye dışarıdan dayatılan, gerçekte gereksiz tüketimi ve statükonun devamını sağlayan arzuları', ['İnsanın hayatta kalması için zorunlu olan beslenme, barınma ve temiz suya erişim gibi biyolojik gereksinimleri', 'Sanatçıların özgün eser üretirken duydukları estetik yaratıcılık ve özgürlük arayışını', 'Vatandaşların adil yargılanma ve ifade özgürlüğü talep etmesini'], 'Marcuse, hayati ihtiyaçların ötesinde "reklamlarla sevdirilen markalara sahip olma, komşusuyla tüketim yarışına girme" gibi dayatmaları yanlış ihtiyaçlar olarak tanımlar.'),
  ('Adorno ve Horkheimer\'a göre kültür endüstrisinin ürettiği filmlerin ve popüler romanların olay örgüsündeki en belirgin yapısal özellik nedir?', 'Sonucun daha en başından tahmin edilebilir olması ve klişelerin sürekli tekrarlanarak zihinsel çaba gerektirmemesi', ['İzleyiciyi derin felsefi çelişkilerle baş başa bırakan açık uçlu ve sarsıcı finallere sahip olması', 'Her eserin önceki tüm sanatsal kuralları yıkan deneysel bir dil icat etmesi', 'Seyircinin salondan çıktıktan sonra toplumsal eşitsizliklere karşı örgütlenmesini sağlaması'], 'Kültür endüstrisi ürünlerinde standartlaşma esastır; izleyici ilk sahneden kimin ödüllendirilip kimin cezalandırılacağını bilir, şema asla bozulmaz.'),
  ('McLuhan\'a göre matbaa teknolojisi (tipografik kültür) Batı toplumunda aşağıdaki dönüşümlerden hangisinin doğmasına doğrudan zemin hazırlamıştır?', 'Standart ulusal dillerin, ulus-devlet bilincinin, bireyciliğin ve doğrusal-analitik düşünme alışkanlığının', ['Sözlü kabile geleneklerinin, büyücülüğün ve ortak köy mülkiyetinin', 'Okuryazarlığın tamamen ortadan kalkarak insanların yalnızca işaret diliyle anlaşmasının', 'Yerel lehçelerin güçlenerek merkezi devlet otoritelerinin tamamen dağılmasının'], 'Matbaa, satır satır soldan sağa tek başına okuma pratiğiyle bireyselleşmeyi, doğrusal mantığı ve basılı ulusal dil etrafında ulus-devleti beslemiştir.'),
  ('McLuhan\'ın "dikiz aynası" (rear-view mirror) metaforu, insanların yeni ortaya çıkan bir iletişim teknolojisini başlangıçta nasıl algıladığını açıklar?', 'Yeni bir aracın ilk içeriklerinin her zaman bir önceki eski aracın biçimleriyle doldurularak geçmişin kalıplarıyla anlamlandırıldığını', ['İnsanların yalnızca otomobil kullanırken radyo dinleyebildiğini', 'Gelecekte icat edilecek tüm teknolojilerin gazeteler tarafından önceden hatasız biçimde tahmin edildiğini', 'İletişim araçlarının yalnızca tarihsel belgesel yayınlamak amacıyla kullanıldığını'], 'Örneğin ilk matbaa kitaplarının el yazmalarını, ilk sinema filmlerinin tiyatroyu, ilk televizyonun radyoyu taklit etmesi "geleceğe dikiz aynasından bakarak yürümek"tir.'),
  ('Sınırlı etkiler ve kullanımlar-doyumlar yaklaşımlarında sıkça başvurulan "seçici maruz kalma" (selective exposure) kavramı aşağıdakilerden hangisini tanımlar?', 'Bireylerin kendi mevcut inanç, tutum ve görüşleriyle uyumlu medya içeriklerini tercih edip çelişen yayınlardan kaçınma eğilimini', ['Devlet kurumlarının yalnızca belirli saatlerde elektrik vererek yayınları kısıtlamasını', 'Gazete bayilerinin yalnızca en pahalı dergileri ön vitrinde sergilemesini', 'Radyo alıcılarının hava koşullarına bağlı olarak bazı frekansları çekmemesini'], 'Leon Festinger\'in bilişsel çelişki kuramıyla da ilişkili olan seçici maruz kalma, bireyin tutumlarıyla örtüşen kaynaklara yönelmesidir.'),
  ('Aynı tartışma programını izleyen iki rakip parti taraftarının, program bittiğinde kendi destekledikleri adayın çok başarılı olduğunu, rakibin ise hezimete uğradığını düşünmesi hangi mekanizmayla açıklanır?', 'Seçici algılama ve seçici yorumlama', ['Mekanik sinyal bozulması', 'Proksemik alan ihlali', 'Tek aşamalı şırınga etkisi'], 'İzleyiciler aynı mesaja maruz kalsalar bile mevcut tutum ve önyargılarına göre mesajı farklı anlamlandırır (seçici algı) ve lehlerine olan kısımları hatırlar (seçici hatırlama).'),
  ('Adorno\'nun popüler müzik eleştirisinde klasik (ciddi) müzik ile kültür endüstrisinin ürettiği popüler müzik arasında kurduğu temel yapısal fark nedir?', 'Klasik müzikte her detay eserin bütünüyle organik ve özgün bir ilişki kurarken, popüler müzikte parçaların birbirinin yerine takılabilen standart kalıplardan oluşması', ['Popüler müziğin dinleyicide çok yüksek müzikoloji eğitimi ve soyut matematiksel dikkat gerektirmesi', 'Klasik müziğin yalnızca ticari reklam jingle\'ları üretmek amacıyla fabrikalarda bestelenmesi', 'Popüler müzikte hiçbir ritim veya nakarat tekrarının bulunmaması'], 'Adorno\'ya göre popüler müzikte yapı standartlaşmıştır (nakarat ve vuruş kalıpları sabittir); dinleyici zahmetsizce önceden sindirilmiş müziği tüketir.'),
  ('Bir sinema izleyicisinin hafta sonu izlediği büyük bütçeli aksiyon filmindeki kahramanın tüm engelleri aşıp mutlu sona ulaşmasıyla kendi hayatındaki eşitsizliklere geçici olarak katlanabilir hale gelmesi, Frankfurt Okulu\'na göre neyin göstergesidir?', 'Kültür endüstrisinin sahte katarsis (arınma) ve uzlaştırma yoluyla toplumsal rıza üretmesinin', ['İzleyicinin aktif biçimde film endüstrisinin mülkiyet yapısını değiştirmesinin', 'İki aşamalı iletişim akışında kanaat önderlerinin medyayı boykot etmesinin', 'Sıcak araçların soğuk araçlara dönüşerek okuryazarlığı artırmasının'], 'Kültür endüstrisi "mutlu son" ve kaçış vaatleriyle bireyin gerçek yaşamdaki yoksunluklarını telafi ediyormuş gibi yaparak sisteme uyumu yeniden üretir.'),
  ('McLuhan\'ın "akustik (işitsel) uzam" ile "görsel uzam" arasında yaptığı ayrıma göre, elektronik medyanın geri getirdiği akustik uzamın temel özelliği nedir?', 'Belirli bir merkezi ve sınırı olmayan, her yönden aynı anda kuşatan, eşzamanlı ve bütüncül bir algı dünyası yaratması', ['Yalnızca soldan sağa doğru tek bir çizgi üzerinde ilerleyen ardışık ve parçalı bir mantık dayatması', 'İnsanların sesleri duymasını engelleyerek yalnızca sessiz okuma alışkanlığı kazandırması', 'Bireyi toplumdan tamamen kopararak kütüphane odalarına hapsetmesi'], 'Görsel uzam (alfabe/matbaa) doğrusal, ardışık ve bireyci iken; sözlü kültür ve elektronik medyanın akustik uzamı eşzamanlı, küresel ve katılımcıdır.'),
  ('Bir belediyenin geri dönüşüm kampanyasını mahalle muhtarları, apartman yöneticileri ve yerel esnaf derneği başkanları üzerinden halka anlatmayı seçmesi hangi iki kavramın birlikte kullanılmasına dayanır?', 'Kanaat önderliği ve birincil grup etkisi', ['Kültür endüstrisi ve sahte bireyselleşme', 'Sıcak medya ve tipografik yalnızlaşma', 'Semantik gürültü ve kamusal mesafe'], 'Muhtarlar ve yerel öncüler yüz yüze güven ilişkilerine dayalı birincil/yerel ağlarda kanaat önderi olarak kitle iletişiminin ikna gücünü artırır.'),
  ('Kullanımlar ve doyumlar kuramının internet ve sosyal medya çağında yeniden büyük popülerlik kazanmasının en önemli kuramsal nedeni aşağıdakilerden hangisidir?', 'Dijital medyanın yüksek etkileşimlilik, içerik seçme ve kullanıcı türevli üretim imkanlarıyla "aktif kullanıcı" varsayımına çok uygun düşmesi', ['İnternet kullanıcılarının hiçbir seçim hakkı olmadan gün boyu tek bir devlet kanalını izlemek zorunda kalması', 'Sosyal medya platformlarının insanlar arasındaki tüm iletişimi yasaklaması', 'Dijital araçların yalnızca tek yönlü telgraf sinyalleri gönderebilmesi'], 'Geleneksel yayıncılığa kıyasla internet; arama, tıklama, yorum yapma ve içerik üretme pratikleriyle kullanımlar ve doyumlar kuramındaki "aktif izleyici/kullanıcı" modelini somutlaştırmıştır.'),
  ('Sınıfta dersi sürekli bölen bir öğrenciye öğretmenin "Sen zaten terbiyesiz ve saygısız bir öğrencisin!" demesi yerine "Ben konu anlatırken yüksek sesle konuştuğunda dikkatim dağılıyor ve dersi yetiştiremeyeceğim için geriliyorum" demesi hangi dönüşümü sağlar?', 'Kişiliği etiketleyen sen dilinden, somut davranışı ve etkiyi belirten yapıcı ben diline geçişi', ['Empatik dinlemeden otoriter tek yönlü propagandaya geçişi', 'Yüksek bağlamlı iletişimden mekanik sinyal aktarımına geçişi', 'Kişisel mesafeden mahrem mesafeye geçişi'], 'İlk cümle öğrencinin karakterine saldıran sen dilidir; ikinci cümle ise davranış-etki-duygu formülüne dayalı ben dilidir.'),
  ('Bir doktorun muayene odasında hastasıyla konuşurken aradaki dev makam masasını kaldırıp hastanın yanındaki sandalyeye (yaklaşık 1 metre mesafeye) oturması sözsüz iletişimde neyi amaçlar?', 'Hiyerarşik engeli azaltarak güven verici, eşitlikçi ve destekleyici bir iletişim atmosferi kurmayı', ['Hastanın mahrem mesafesini zorla ihlal ederek üzerinde psikolojik baskı oluşturmayı', 'Muayene süresini kısaltarak hastanın soru sormasını engellemeyi', 'Kamusal mesafeye geçerek hastaya resmi bir konferans vermeyi'], 'Masanın fiziksel bariyer olarak kaldırılması proksemik ve çevresel düzenlemeyle otorite mesafesini yumuşatır, açık iletişimi destekler.'),
  ('İki aşamalı iletişim akışı modelinde kanaat önderlerinin kitle iletişim araçlarına kıyasla bireyleri ikna etmede daha başarılı olmasının temel psikolojik nedeni nedir?', 'Yüz yüze iletişimin esnek olması, anında geri bildirim sağlaması ve kişisel güven ilişkisine dayanması', ['Kanaat önderlerinin televizyon uydularından daha güçlü elektromanyetik dalga yayması', 'Bireylerin tanıdıkları insanların söylediklerini sorgulama yeteneğinden tamamen yoksun olması', 'Kanaat önderlerinin her zaman yasal yaptırım ve para cezası uygulama yetkisinin bulunması'], 'Katz ve Lazarsfeld\'e göre yüz yüze etkileşim niyet açısından daha az çıkar odaklı algılanır, direnç anında mesajı kişiye göre uyarlayabilir ve grup onayı sağlar.'),
  ('Yalnız yaşayan yaşlı bir bireyin evdeki sessizliği gidermek ve ekrandaki sabah programı sunucusunu aileden biri gibi görerek her gün aynı saatte programı açması kullanımlar ve doyumlar kuramında hangi işlevi örneklendirir?', 'Yalnızlıktan kurtulma ve parasosyal etkileşim doyumu', ['Mesleki teknik beceri geliştirme doyumu', 'Siyasal propaganda üretme doyumu', 'Kanaat önderliği yaparak çevresini örgütleme doyumu'], 'Medyanın gerçek sosyal ilişkilerin eksikliğini ikame edecek şekilde yoldaşlık sağlaması parasosyal etkileşim ve duygusal/sosyal doyumdur.'),
  ('Marshall McLuhan\'ın bir konuşma veya metinden çok kendi kuramının özeti haline gelen ve "Araç mesajdır" sözünün kelime oyunuyla basılmış kitap başlığı da olan diğer ünlü ifadesi hangisidir?', 'Araç masajdır (The medium is the massage)', ['Araç gürültüdür (The medium is the noise)', 'Araç sansürdür (The medium is the censor)', 'Araç aynadır (The medium is the mirror)'], 'Dizgi hatasıyla ortaya çıkıp McLuhan\'ın çok beğenerek koruduğu "The Medium is the Massage" başlığı, medyanın insan duyularını adeta yoğurup masaj yaparak şekillendirdiğini vurgular.'),
  ('Etkin dinleme sürecinde açık uçlu sorular ("Bu durum seni nasıl etkiledi?") ile kapalı uçlu sorular ("Üzüldün mü?") karşılaştırıldığında açık uçlu soruların iletişimsel üstünlüğü nedir?', 'Konuşmacıyı "evet/hayır" kalıbına sıkıştırmadan kendi duygu ve düşüncelerini kendi çerçevesiyle derinlemesine anlatmasına alan açması', ['Konuşmayı en kısa sürede bitirerek dinleyicinin zaman kazanmasını sağlaması', 'Konuşmacının konuyu değiştirmesini zorlaştırarak onu savunmaya zorlaması', 'Dinleyicinin kendi uzmanlık bilgisini kanıtlamasına fırsat vermesi'], 'Açık uçlu sorular yönlendirici değildir; konuşmacının iç dünyasını keşfetmesini ve anlatıyı genişletmesini destekler.'),
  ('Toplantı sırasında kollarını göğsünde sıkıca kavuşturup sandalyesinde geriye yaslanan ve bakışlarını kaçıran bir katılımcının beden dili, bağlamla birlikte değerlendirildiğinde genellikle nasıl bir tutuma işaret eder?', 'İletişime kapalılık, savunmacılık veya anlatılan görüşe mesafeli durma', ['Anlatılan fikre tam bir coşkuyla katılma ve söz almak için sabırsızlanma', 'Karşı tarafla samimi ve mahrem bir dostluk başlatma isteği', 'Konuşmacının söylediklerini not almak için yüksek odaklanma'], 'Tek bir hareket kesin kanıt olmasa da kolları kavuşturma, geriye çekilme ve göz kaçırma kümesi savunmacı/kapalı postür göstergesidir.'),
];
